-- ===== PROCEDURE __CheckBalances (recovered from backup text; may be incomplete) =====
CREATE PROCEDURE [dbo].[__CheckBalances]
SET NOCOUNT ON;
CREATE TABLE #ChashFlow 
(BankName varchar(100), BranchName varchar(100), BankAccNo varchar(50), Balance bigint);
CREATE TABLE #GetAllBankBalance
(Balance bigint, Daryaft bigint, Opening bigint, Pardakht bigint, BasicBankId int, BankName varchar(100),
BankId int, BranchName varchar(100), BankAccNo varchar(50));
TRUNCATE TABLE #ChashFlow;
INSERT INTO #ChashFlow EXEC CashFlow '99999999', '99999999';
TRUNCATE TABLE #GetAllBankBalance;
INSERT INTO #GetAllBankBalance EXEC GetAllBankBalance '', '99999999';
SELECT 
	ISNULL(a.BankAccNo, b.BankAccNo) AS BankAccNo, ISNULL(a.BankName, b.BankName) AS BankName,
	ISNULL(a.BranchName, b.BranchName) AS BranchName, a.Balance AS CashFlowbalance, b.Balance AS AllBankBalance,
	ISNULL(a.Balance, 0) - ISNULL(b.Balance, 0) AS Diff
FROM #ChashFlow a
FULL OUTER JOIN #GetAllBankBalance b
	ON a.BankAccNo = b.BankAccNo
WHERE ISNULL(a.Balance, 0) <> ISNULL(b.Balance, 0)
GO

