-- ===== PROCEDURE _ESLAHE_ASNADpARDAKHTANI (recovered from backup text; may be incomplete) =====
CREATE PROCEDURE [dbo].[_ESLAHE_ASNADpARDAKHTANI]
SELECT  *    
into #tmp1
FROM [Voucher_Row] 
where unique_account_no like '02%' and account_no like '32011%'
select  rowid , a.Account_No ,  AccVoucherNo , A.unique_account_no , B.unique_account_no as unique_account_no1 
into #tmp2
from #tmp1 a inner join request_payment b on a.referenceid = b.requestid
--inner join banks s on s.bankid = b.Source_PaymentValue
 --SELECT * FROM #TMP2
 update a
  set a.unique_account_no = b.unique_account_no1
  from Voucher_Row  a inner join #tmp2 b on a.accvoucherno = b.accvoucherno and a.account_no = b.account_no 
 and a.unique_account_no = b.unique_account_no 
 update a
 set   a.unique_account_no = b.unique_account_no1
 from Accyaran1401..t_voucher_row a inner join #tmp2 b on a.voucher_no = b.accvoucherno and a.account_no = b.account_no 
 and a.unique_account_no = b.unique_account_no 
UPDATE A 
SET A.UNIQUE_ACCOUNT_NO =  B.UNIQUE_ACCOUNT_NO
FROM Accyaran1401..T_VOUCHER_ROW A INNER JOIN Voucher_Row B 
ON A.VOUCHER_NO = B.ACCVOUCHERNO 
WHERE A.Account_No = '32011' AND A.Unique_Account_No  LIKE '02%'
AND B.Account_No = '32011' AND B.Unique_Account_No  NOT LIKE '02%'
drop table #tmp1 
drop table #tmp2
