-- ===== PROCEDURE _EslaheBank (recovered from backup text; may be incomplete) =====
 CREATE procedure [dbo].[_EslaheBank]
 -- badan bayad routin eslah shavad ke in sp digar run nashavad
SELECT  *    
into #tmp1
  FROM [Treasury].[dbo].[Voucher_Row] 
  where unique_account_no not like '02%' and account_no like '11012%'
 select  rowid , a.Account_No ,  AccVoucherNo ,  b.unique_account_no , s.unique_account_no as unique_account_no1 
 into #tmp2
 from #tmp1 a inner join request_payment b on a.referenceid = b.requestid
 inner join banks s on s.bankid = b.Source_PaymentValue
 update a
  set a.unique_account_no = b.unique_account_no1
  from Voucher_Row  a inner join #tmp2 b on a.accvoucherno = b.accvoucherno and a.account_no = b.account_no 
 and a.unique_account_no = b.unique_account_no 
 update a
 set   a.unique_account_no = b.unique_account_no1
 from Accyaran1400..t_voucher_row a inner join #tmp2 b on a.voucher_no = b.accvoucherno and a.account_no = b.account_no 
 and a.unique_account_no = b.unique_account_no 
 drop table #tmp1 
 drop table #tmp2
