-- ===== PROCEDURE _GetRequestPaymentStatus (recovered from backup text; may be incomplete) =====
CREATE PROCEDURE [dbo].[_GetRequestPaymentStatus]
 @CurrentDate varchar(8),
  @Unique_Account_No varchar(50),
   @SystemId as varchar(10),
    @SystemReferenceID  as varchar(100)
 SET NOCOUNT ON
  --declare @CurrentDate varchar(8)
--set @CurrentDate = '13950822'
 declare @temp table
(States	 varchar(50),
DueDate	 varchar(8),
PayAmount	 bigint,
RequestID	bigint ,
RequestDate	 varchar(50),
Unique_Account_No	 varchar(50),
Account_Name	 varchar(150),
BehalfDescription  varchar(250),
BehalfGroupID int,
ChequeNo	bigint ,
Title	 varchar(250),
ForSodooreCheck	 int ,
Bank_AccountNumber  varchar(150) ,
TahvilDadeShodeh tinyint 
declare @wherestr varchar(500)
if @SystemReferenceID='' 
begin 
insert into @temp  EXEC Get_Maturity_Cheques     @CurrentDate
select   a.* ,  b.*  ,v.Account_Name ,be.BehalfDescription,ba.Bank_AccountNumber,bas.BasicBankDescription, case when c.RequestID Is null then 1 else 0 end as MozavezeChapeChequeDarad , dbo.MojavezeEmza(a.RequestID) as mojavezeEmza
--into TMP
  from Request_Payment  a left join @temp c on a.RequestID = c.RequestID 
  left join v_unique_accounts v on a.Unique_Account_No=v.Account_Code
  left join Behalfs be on be.BehalfID=a.BehalfID
  left join Banks ba on a.Source_PaymentValue=ba.BankID
  left join BasicBanks bas on bas.BasicBankId=ba.BasicBankID
CROSS APPLY  dbo.GetRequestStatus( a.RequestID ) b 
where (a.Unique_Account_No=@Unique_Account_No) and (SystemId=@SystemId) 
