-- ===== PROCEDURE _Send_voucher_SpecialDate_PettyCash (recovered from backup text; may be incomplete) =====
CREATE PROCEDURE [dbo].[_Send_voucher_SpecialDate_PettyCash]
     @currentDate char(8)
--declare  @currentDate char(8)
--set @currentDate = 13961002
declare @AccDbName varchar(20)
set @AccDbName = isnull((SELECT  TOP (1) AccDatabaseName FROM   Config WHERE     (@currentDate BETWEEN FiscalYearStart AND FiscalYearEnd)) , '')
if @AccDbName = '' 
   return;
DECLARE  @SQL VARCHAR(MAX) 
SET @SQL = 
'if exists(select Voucher_No from ' + @AccDbName + '.dbo.t_voucher where Voucher_date = ' + @currentDate + ' and Is_Updated = 1)
   return;
declare @TAG	VARCHAR(20) , @Date1 char(8) 
declare @PettyCashTransactionHeaderID decimal(18,0)
declare vn_cursor0 cursor 
 select distinct a.PettyCashTransactionHeaderID , a.PettyCashTransactionDate
  FROM  PettyCash_TransactionHeader a inner join   [PettyCash_TransactionDetail] b on 
  a.PettyCashTransactionHeaderID = b.PettyCashTransactionHeaderID 
  inner join Behalfs on Behalfs.BehalfID  = b.BehalfID inner join PettyCash on a.PettyCashID = PettyCash.PettyCashID 
  inner join UserInfo on PettyCash.UserID = UserInfo.UserID inner join LocationByCostCenters  on UserInfo.LocationByCostCenterID = LocationByCostCenters.LocationByCostCenterID    
 where PettyCashTransactionDate  = ' + @currentDate + ' and b.IsAccept = 1
 declare @Vn bigint 
declare @HazineGroupAccountCode char(1)
set @HazineGroupAccountCode = ''7''
 open vn_cursor0
 FETCH NEXT FROM vn_cursor0 into  @PettyCashTransactionHeaderID   , @Date1
 WHILE @@FETCH_STATUS = 0 
 BEGIN 
	     
		set @TAG = ''PETTY'' + @Date1 + ''-''  +  CAST(@PettyCashTransactionHeaderID as varchar(10))
		set @Vn = isnull( ( select voucher_no from ' + @AccDbName + '.dbo.t_voucher where Tag = @TAG ) , 0 ) 
		Select * , ROW_NUMBER() OVER(ORDER BY PettyCashTransactionDetailID ASC)     as record_no into #tmp1 from Create_Voucher_PettyCash_func( @PettyCashTransactionHeaderID , @HazineGroupAccountCode )
          
		update A
		set A.unique_account_no = '''' 
		FROM #tmp1 A inner join v_accounts b on A.account_no = b.account_code 
		where b.Has_Unique_Account = 0
          
        if @Vn = 0  
        begin
           insert into  ' + @AccDbName + '.dbo.t_voucher (Voucher_Date , Voucher_Type , source_type , Tag , modification_type , sumation , Is_Updated , [Description]  )
           select distinct @Date1 , 0 , 3 , @TAG , 3 , SUM(credit) , 0   , MAX(desc1)           from #tmp1            where credit <> 0
           
           
           set @Vn = (select MAX(voucher_no) from ' + @AccDbName + '.dbo.t_voucher where source_type = 3)
           
        end 
        delete from  ' + @AccDbName + '.dbo.t_voucher_row where Voucher_No = @Vn and Voucher_No in (select Voucher_No from ' + @AccDbName + '.dbo.t_voucher where Voucher_No = @Vn and source_type = 3)
        
        insert into  ' + @AccDbName + '.dbo.t_voucher_row(Voucher_No , Account_No , Unique_Account_No , Unique_Account_No_two , Description , Debit , Credit , SystemRef , Record_No )
		select @vn ,  Account_no , Unique_Account_No , Unique_Account_No_two , Desc1 , Debit , Credit ,PettyCashTransactionDetailID , record_no 
		from #tmp1 
       drop table #tmp1
       
       update PettyCash_TransactionHeader set AccVoucherNo = @Vn where PettyCashTransactionHeaderID = @PettyCashTransactionHeaderID
