-- ===== FUNCTION CanEditReceiptDetail (recovered from backup text; may be incomplete) =====
CREATE FUNCTION [dbo].[CanEditReceiptDetail](@ReceiptDetailId decimal(18, 0))
RETURNS bit
	IF (SELECT COUNT(*)
		FROM Receipt_Detail_PlanState
		WHERE ReceiptDetailId = @ReceiptDetailId) = 1
	BEGIN
		IF NOT EXISTS(SELECT 1
					FROM Receipt_Detail a
					WHERE a.ReceiptDetailId = @ReceiptDetailId
						AND EXISTS(SELECT 1 FROM Reciept_Header b WHERE a.ReceiptId = b.ReceiptId AND b.ReferenceReceiptId > 0))
			RETURN 1;
	RETURN 0;
GO

-- ===== PROCEDURE CashFlow (recovered from backup text; may be incomplete) =====
CREATE PROCEDURE [dbo].[CashFlow]
@ToDate						char(8),
@ToFutureDate				char(8),
@NazdeSandoghMarkaz			bigint OUTPUT,
@NazdeSandoghKharejAzMarkaz bigint OUTPUT
SET NOCOUNT ON;
SELECT
	@NazdeSandoghMarkaz = ISNULL(SUM(CASE WHEN b.CityID = c.CityID THEN b.ChequePrice_Rial ELSE 0 END), 0),
	@NazdeSandoghKharejAzMarkaz = ISNULL(SUM(CASE WHEN b.CityID <> c.CityID THEN b.ChequePrice_Rial ELSE 0 END), 0)
FROM Receipt_Detail_PlanState a
INNER JOIN Receipt_Detail b
	ON a.ReceiptDetailId = b.ReceiptDetailId
CROSS JOIN (SELECT CityID FROM cmpBranches WHERE IsMainBranch = 1) c
WHERE a.PlaningTypeID = 1
	AND a.StateDate <= @ToDate
	AND @ToFutureDate >= @ToDate
	AND NOT EXISTS(SELECT 1
					FROM Receipt_Detail_PlanState rdp
					WHERE a.ReceiptDetailId = rdp.ReceiptDetailId
					AND rdp.PlaningTypeID > a.PlaningTypeID);
SELECT b.BasicBankDescription, a.BranchName, a.Bank_AccountNumber,
	ISNULL(c.EquivalencePrice, 0) + a.OpeningValue AS Balance,
	ISNULL(d.PardakhtaniSarresidGozashte, 0) AS PardakhtaniSarresidGozashte,
	ISNULL(d.TaahodatEmrooz, 0) AS TaahodatEmrooz,
	ISNULL(d.PardakhtanihaTa, 0) AS PardakhtanihaTa,
	--ISNULL(c.EquivalencePrice, 0) + a.OpeningValue - ISNULL(d.PardakhtaniSarresidGozashte, 0) AS MojoodiMotamen,
	ISNULL(e.DarjaryanVosoolMarkaz, 0) AS DarjaryanVosoolMarkaz,
	--ISNULL(c.EquivalencePrice, 0) + a.OpeningValue - ISNULL(d.PardakhtaniSarresidGozashte, 0) +
	--	ISNULL(e.DarjaryanVosoolMarkaz, 0) AS MojoodiMotamenPlusDarjaryanVosoolMarkaz,
	ISNULL(e.DarjaryanVosoolKharejAzMarkaz, 0) AS DarjaryanVosoolKharejAzMarkaz
	--ISNULL(c.EquivalencePrice, 0) + a.OpeningValue - ISNULL(d.PardakhtaniSarresidGozashte, 0) +
	--	ISNULL(e.DarjaryanVosoolMarkaz, 0) + ISNULL(e.DarjaryanVosoolKharejAzMarkaz, 0) AS Total
FROM Banks a
INNER JOIN BasicBanks b
	ON a.BasicBankID = b.BasicBankId
LEFT OUTER JOIN
	SELECT Unique_Account_No, SUM(EquivalencePrice) AS EquivalencePrice
		SELECT a.Unique_Account_No, SUM(b.ChequePrice_Rial) AS EquivalencePrice
		FROM Receipt_Detail_PlanState a
		INNER JOIN Receipt_Detail b
			ON a.ReceiptDetailId = b.ReceiptDetailId
		INNER JOIN PlaningType c
			ON a.PlaningTypeID = c.PlaningTypeID
		WHERE c.EffectiveForBank = 1
			AND a.StateDate <= @ToDate
			AND @ToFutureDate >= @ToDate
		GROUP BY a.Unique_Account_No
		UNION ALL
		SELECT c.Unique_Account_No,	-SUM(a.EquivalencePrice - ISNULL(f.Price, 0)) AS EquivalencePrice
		FROM Request_Payment a
		INNER JOIN Payment b
			ON a.RequestID = b.RequestID
		INNER JOIN Banks c
			ON a.Source_PaymentValue = c.BankID
		INNER JOIN Receipt_Pay_TypeDetail d
			ON a.Pay_TypeDetailID_source = d.Receipt_Pay_TypeDetailID
		INNER JOIN Request_Payment_StatusDetails e
			ON a.RequestID = e.RequestID
		LEFT OUTER JOIN TransferFromBackupBank f
			ON a.RequestID = f.RequestID
				AND f.IsOk = 1
				AND f.OkDate <= @ToDate
				--AND a.Source_PaymentValue = f.To_BankID -- extra check. when a.RequestID = f.RequestID then a.Source_PaymentValue = f.To_BankID is always true
		WHERE d.EffectiveForBank = 1
			AND e.RequestStatusTypeID = 4
			AND b.PaymentDate <= @ToDate
			AND @ToFutureDate >= @ToDate
		GROUP BY c.Unique_Account_No
		UNION ALL
		SELECT e.Unique_Account_No,	-SUM(d.Price) AS EquivalencePrice
		FROM Request_Payment a
		INNER JOIN Payment b
			ON a.RequestID = b.RequestID
		INNER JOIN Request_Payment_StatusDetails c
			ON a.RequestID = c.RequestID
		INNER JOIN TransferFromBackupBank d
			ON a.RequestID = d.RequestID
		INNER JOIN Banks e
			ON d.From_BankID = e.BankID
		WHERE c.RequestStatusTypeID = 4
			AND b.PaymentDate <= @ToDate
			AND d.IsOk = 1
			AND d.OkDate <= @ToDate
			AND @ToFutureDate >= @ToDate
		GROUP BY e.Unique_Account_No
	GROUP BY Unique_Account_No
	ON a.Unique_Account_No = c.Unique_Account_No
LEFT OUTER JOIN
	SELECT c.Unique_Account_No,
		SUM(CASE WHEN a.DueDate < @ToDate THEN a.EquivalencePrice ELSE 0 END) AS PardakhtaniSarresidGozashte,
		SUM(CASE WHEN a.DueDate = @ToDate THEN a.EquivalencePrice ELSE 0 END) AS TaahodatEmrooz,
		SUM(a.EquivalencePrice) AS PardakhtanihaTa
	FROM Request_Payment a
	INNER JOIN Request_Payment_StatusDetails b
		ON a.RequestID = b.RequestID
	INNER JOIN Banks c
		ON a.Source_PaymentValue = c.BankID
	WHERE a.Pay_TypeDetailID_source = 4
		AND b.RequestStatusTypeID = 4
		AND a.DueDate <= @ToFutureDate
		AND @ToFutureDate >= @ToDate
		AND NOT EXISTS(SELECT 1 FROM Payment py WHERE a.RequestID = py.RequestID)
	GROUP BY c.Unique_Account_No
	ON a.Unique_Account_No = d.Unique_Account_No
LEFT OUTER JOIN
	SELECT a.Unique_Account_No,
		SUM(CASE WHEN b.CityID = c.CityID THEN b.ChequePrice_Rial ELSE 0 END) AS DarjaryanVosoolMarkaz,
		SUM(CASE WHEN b.CityID <> c.CityID THEN ISNULL(b.ChequePrice_Rial, 0) ELSE 0 END) AS DarjaryanVosoolKharejAzMarkaz
	FROM Receipt_Detail_PlanState a
	INNER JOIN Receipt_Detail b
		ON a.ReceiptDetailId = b.ReceiptDetailId
	CROSS JOIN (SELECT CityID FROM cmpBranches WHERE IsMainBranch = 1) c
	WHERE a.PlaningTypeID = 2
		AND a.StateDate <= @ToDate 
		AND @ToFutureDate >= @ToDate
		AND NOT EXISTS(SELECT 1
					   FROM Receipt_Detail_PlanState rdp
					   WHERE a.ReceiptDetailId = rdp.ReceiptDetailId
						AND rdp.PlaningTypeID > a.PlaningTypeID)
	GROUP BY a.Unique_Account_No
	ON a.Unique_Account_No = e.Unique_Account_No;
-- EXEC __CheckBalances
GO

-- ===== PROCEDURE ChangeVakhahiHeader (recovered from backup text; may be incomplete) =====
CREATE PROCEDURE [dbo].[ChangeVakhahiHeader]
@PettyCashTransactionHeaderID	decimal(18, 0)
SET NOCOUNT ON;
DECLARE @Ret decimal(18, 0) = 0;
UPDATE a
SET PettyCashTransactionHeaderID = @PettyCashTransactionHeaderID
FROM PettyCash_TransactionDetail a
INNER JOIN PettyCash_TransactionHeader b
	ON a.PettyCashTransactionHeaderID = b.PettyCashTransactionHeaderID
INNER JOIN PettyCash_TransactionHeader c
	ON b.PettyCashID = c.PettyCashID
		AND b.PettyCashTransactionDate <= c.PettyCashTransactionDate
WHERE a.IsVakhahi = 1
	AND b.IsConfirm = 1
	AND c.IsConfirm = 0
	AND c.PettyCashTransactionHeaderID = @PettyCashTransactionHeaderID;
IF @@ROWCOUNT > 0
	SET @Ret = @PettyCashTransactionHeaderID;
RETURN @Ret;
GO

