-- ===== PROCEDURE DeleteRowFromAccounting (recovered from backup text; may be incomplete) =====
Create procedure [dbo].[DeleteRowFromAccounting]
 @AccVoucherNo int , @date1 char(8) ,  @Receipt_Pay   int , @ReferenceId bigint
--declare @AccVoucherNo int , @date1 char(8)
declare @ForRec varchar(500) 
set @ForRec = ' and 1=1'
if @Receipt_Pay <> 1  -- yani daryaf bood , bayad satre marbood be stateid khass ra hazf konad
 begin 
   -- baraye sherkathayi ke pattern e tag e oona bar asase date ast bayad taghyir konad
   set @ForRec =  ' and SystemRef like ''REC%'' and SystemRef like ''%-''  + ''' + cast(@ReferenceId as varchar(50)) +  ''''
declare @s varchar(200)
declare @s2 varchar(100)
set @s =  cast(@AccVoucherNo  as varchar(50)) + ' ' + @ForRec 
set @s2 = cast(@AccVoucherNo  as varchar(50))
declare @AccDatabaseName varchar(50)
    set @AccDatabaseName = (SELECT  top 1 [AccDatabaseName] FROM  [Config] where @date1 between [FiscalYearStart] and [FiscalYearEnd])
	if @AccDatabaseName = '' 
	   return;
--	select @AccDatabaseName
exec('
	if exists(select top 1 voucher_no from ' +  @AccDatabaseName  + '..t_voucher where Voucher_No = ' +  @s2 + '  and Is_Updated = 0 and source_type = 3)
	begin
		delete from  ' +  @AccDatabaseName  + '..t_voucher_row where Voucher_No = ' + @s + '
GO

-- ===== PROCEDURE DelReceipt_Detail_PlanStates (recovered from backup text; may be incomplete) =====
CREATE PROCEDURE [dbo].[DelReceipt_Detail_PlanStates]
@ReceiptDetailId int
SET NOCOUNT ON;
DELETE FROM Receipt_Detail_PlanState
WHERE ReceiptDetailId = @ReceiptDetailId AND PlaningTypeID <> 1;
GO

-- ===== PROCEDURE DelTavizReceipt_Detail_PlanStates (recovered from backup text; may be incomplete) =====
CREATE PROCEDURE [dbo].[DelTavizReceipt_Detail_PlanStates]
@ReceiptDetailId	int,
@StateID			decimal(18, 0)
SET NOCOUNT ON;
;WITH cte
	SELECT b.ReceiptDetailId
	FROM Receipt_Detail_PlanState a
	INNER JOIN Receipt_Detail b
		ON a.ReceiptDetailId = b.ReceiptDetailId
	WHERE a.ReceiptDetailId = @ReceiptDetailId
		AND a.StateID = @StateID
		AND a.PlaningTypeID = 21
DELETE a
FROM Receipt_Detail_PlanState a
INNER JOIN Receipt_Detail b
	ON a.ReceiptDetailId = b.ReceiptDetailId
INNER JOIN Reciept_Header c
	ON b.ReceiptId = c.ReceiptId
INNER JOIN cte d
	ON c.ReferenceReceiptId = d.ReceiptDetailId;
IF @@ROWCOUNT > 0
	;WITH cte
		SELECT b.ReceiptDetailId
		FROM Receipt_Detail_PlanState a
		INNER JOIN Receipt_Detail b
			ON a.ReceiptDetailId = b.ReceiptDetailId
		WHERE a.ReceiptDetailId = @ReceiptDetailId
			AND a.StateID = @StateID
			AND a.PlaningTypeID = 21
	DELETE a
	FROM Receipt_Detail a
	INNER JOIN Reciept_Header b
		ON a.ReceiptId = b.ReceiptId
	INNER JOIN cte c
		ON b.ReferenceReceiptId = c.ReceiptDetailId;
	;WITH cte
		SELECT b.ReceiptDetailId
		FROM Receipt_Detail_PlanState a
		INNER JOIN Receipt_Detail b
			ON a.ReceiptDetailId = b.ReceiptDetailId
		WHERE a.ReceiptDetailId = @ReceiptDetailId
			AND a.StateID = @StateID
			AND a.PlaningTypeID = 21
	DELETE a
	FROM Reciept_Header a
	INNER JOIN cte b
		ON a.ReferenceReceiptId = b.ReceiptDetailId;
DELETE Receipt_Detail_PlanState WHERE ReceiptDetailId = @ReceiptDetailId AND StateID = @StateID;
