CREATE FUNCTION [dbo].[fn_ShamsiDateStrDiffDay] (@FDate varchar(10), @LDate varchar(10))
RETURNS int
declare @FY int, @FM int, @FD int, @LY int, @LM int, @LD int,
@FirstM int, @FirstD int, @LastM int, @LastD int,
@YDiff int, @LDiff int, @FDiff int
set @FY = SUBSTRING(@FDate, 1, 4) 
set @FM = SUBSTRING(@FDate, 5, 2)
set @FD =SUBSTRING(@FDate, 7, 2)
set @LastM = 12
set @LastD = 30
set @LDiff = ((@LastM - @FM) * 30) + (@LastD - @FD)
set @LY =SUBSTRING(@LDate, 1, 4) 
set @LM = SUBSTRING(@LDate, 5, 2) 
set @LD = SUBSTRING(@LDate, 7, 2) 
set @FirstM = 1
set @FirstD = 1
set @FDiff = ((@LM - @FirstM) * 30) + (@LD - @FirstD)+1
set @YDiff = (@LY - (@FY + 1)) * 360;
return @LDiff + @FDiff + @YDiff
GO

-- ===== FUNCTION fn_ShamsiDateStrPart (recovered from backup text; may be incomplete) =====
CREATE FUNCTION [dbo].[fn_ShamsiDateStrPart] (@ADateStr varchar(10), @ADatePart char)
RETURNS int
declare @FY varchar(4), @FM varchar(2), @FD varchar(2),
@SlashPos1 int, @SlashPos2 int
if @ADateStr = '' return null
set @SlashPos1 = CHARINDEX('/', @ADateStr)
if (@SlashPos1 = 0) or ((@SlashPos1 <> 3) and (@SlashPos1 <> 5)) return null
set @SlashPos2 = CHARINDEX('/', @ADateStr, @SlashPos1 + 1)
if @SlashPos2 = 0 return null
set @FY = Cast(SUBSTRING (@ADateStr, 1 , @SlashPos1 - 1 ) as int)
set @FM = Cast(SUBSTRING (@ADateStr, @SlashPos1 + 1, @SlashPos2 - @SlashPos1 - 1) as int)
set @FD = Cast(SUBSTRING (@ADateStr, @SlashPos2 + 1, LEN(@ADateStr) - @SlashPos2) as int)
return
case @ADatePart
when 'Y' then @FY
when 'M' then @FM
when 'D' then @FD
GO

-- ===== FUNCTION fnGetPettyCashBalance (recovered from backup text; may be incomplete) =====
CREATE FUNCTION [dbo].[fnGetPettyCashBalance](@PettyCashID int)
RETURNS decimal(18, 0)
	DECLARE @Balance decimal(18, 0);
	SELECT @Balance =
		ISNULL
					SELECT top 1 cast(a.PettyCash_Ammount as decimal(18, 0))
					FROM PettyCash a
					WHERE PettyCashID = @PettyCashID
				), 0
		ISNULL
					SELECT SUM(c.PayAmount)
					FROM PettyCash  a
					INNER JOIN PettyCash_TransactionHeader b
						ON a.PettyCashID = b.PettyCashID
					INNER JOIN Request_Payment c
						ON b.RequestID = c.RequestID
					INNER JOIN Payment d
						ON b.RequestID = d.RequestID
					WHERE a.PettyCashID = @PettyCashID
						AND a.RecoveryType = 1
				), 0
		ISNULL
					SELECT SUM(b.Price)
					FROM PettyCash_TransactionHeader a
					INNER JOIN PettyCash_TransactionDetail b
						ON a.PettyCashTransactionHeaderID = b.PettyCashTransactionHeaderID
					WHERE a.PettyCashID = @PettyCashID --AND b.IsAccept = 1
				), 0
	RETURN @Balance;
GO

-- ===== PROCEDURE GardesheHesabBank (recovered from backup text; may be incomplete) =====
CREATE PROCEDURE [dbo].[GardesheHesabBank] @BankIdList varchar(100) ,@BankUnique_Account_No varchar(100),@DateFrom varchar(8),@DateTo varchar(8),@ShowRial bit  
--DECLARE @BankUnique_Account_No AS varchar(50)
--DECLARE @BankIdList AS varchar(100)
--declare @DateFrom varchar(8)
--declare @DateTo varchar(8)
--set @DateFrom='13960501'
--set @DateTo='13960601'
--set @BankIdList='5,7'
--set @BankUnique_Account_No='010101,010103'
		select *  into #temp1
		from (
SELECT dbo.BehalfGroup.BehalfGroupDescription as BehalfGroupDescription, Behalfs.BehalfDescription as BehalfDescription, 
	dbo.v_unique_accounts.Account_Name AS Unique_Account_Title, Request_Payment.ChequeNo as ChequeNo,
	SUBSTRING(Request_Payment.DueDate , 1, 4)+'/'+
	SUBSTRING(Request_Payment.DueDate , 5, 2)+'/'+
	SUBSTRING(Request_Payment.DueDate , 7, 2) as DueDate, 
	Receipt_Pay_TypeDetail.Receipt_Pay_TypeDetailDescription as TypeOfCheque ,
	dbo.BasicBanks.BasicBankDescription as BasicBankDescription, dbo.Banks.BranchName as BranchName, dbo.Banks.BranchCode as BranchCode, 
	dbo.Banks.Bank_AccountNumber as Bank_AccountNumber,dbo.Banks.Unique_Account_No as BankUnique_Account_No,
	1 as Type,dbo.Banks.BankID as BankID,dbo.Banks.OpeningValue as OpeningValue, cast (0 as decimal(18,0)) as priceDaryaft,
	PayAmount,Request_Payment.ExchangeRate , cast (Request_Payment.EquivalencePrice as decimal(18,0))  as PricePardakht,
	cast (0 as decimal(18,0)) as mandeh
		FROM            dbo.GetLastRequestStatus() AS GetLastRequestStatus_1
		          INNER join Request_Payment ON GetLastRequestStatus_1.Request_Payment_Status_RequestID = Request_Payment.RequestID
				  INNER join Behalfs ON Request_Payment.BehalfID = Behalfs.BehalfID 
				  INNER join BehalfGroup ON Behalfs.BehalfGroupID = dbo.BehalfGroup.BehalfGroupID
				  INNER join Receipt_Pay_TypeDetail ON Request_Payment.Pay_TypeDetailID_source = Receipt_Pay_TypeDetail.Receipt_Pay_TypeDetailID 
				  LEFT OUTER join v_unique_accounts ON Request_Payment.Unique_Account_No = dbo.v_unique_accounts.Account_Code
		          INNER join Banks ON Request_Payment.Source_PaymentValue = dbo.Banks.BankID 
				  INNER join BasicBanks ON dbo.Banks.BasicBankID = dbo.BasicBanks.BasicBankId 
								  where Request_Payment_Status_RequestStatusTypeID=3 and   Source_PaymentValue  in( @BankIdList )  and  DueDate >= @DateFrom  and DueDate <=@DateTo
								  union all 
SELECT dbo.BehalfGroup.BehalfGroupDescription as BehalfGroupDescription, Behalfs.BehalfDescription as BehalfDescription, 
	dbo.v_unique_accounts.Account_Name as Account_Name, dbo.Receipt_Detail.Cheque_Number as Cheque_Number, 
	dbo.Receipt_Detail.DueDate as DueDate, GetLast_Receipt_Detail_PlanState_Status_1.PlaningTypeDesc,
	dbo.BasicBanks.BasicBankDescription as BasicBankDescription, dbo.Banks.BranchName as  BranchName, dbo.Banks.BranchCode as BranchCode, 
	dbo.Banks.Bank_AccountNumber as Bank_AccountNumber,dbo.Banks.Unique_Account_No as BankUnique_Account_No,
	2 as type,dbo.Banks.BankID as BankID,dbo.Banks.OpeningValue as OpeningValue,ChequePrice_Rial,dbo.Receipt_Detail.ExchangeRate , 
	cast (EquivalencePrice as bigint)  as priceDaryaft , cast (0 as decimal(18,0)) as PricePardakht, cast (0 as decimal(18,0)) as mandeh
		FROM            dbo.GetLast_Receipt_Detail_PlanState_Status() AS GetLast_Receipt_Detail_PlanState_Status_1
		          INNER join Receipt_Detail ON GetLast_Receipt_Detail_PlanState_Status_1.ReceiptDetailId = dbo.Receipt_Detail.ReceiptDetailId 
				  INNER join Behalfs ON dbo.Receipt_Detail.BehalfID = Behalfs.BehalfID
				  INNER join BehalfGroup ON Behalfs.BehalfGroupID = dbo.BehalfGroup.BehalfGroupID
				  INNER join v_unique_accounts ON dbo.Receipt_Detail.Unique_Account_No = dbo.v_unique_accounts.Account_Code 
				  INNER join Banks ON GetLast_Receipt_Detail_PlanState_Status_1.Unique_Account_No = dbo.Banks.Unique_Account_No
				  INNER join BasicBanks ON dbo.Banks.BasicBankID = dbo.BasicBanks.BasicBankId
								 where PlaningTypeID in (2,4,11) and   charindex(cast( GetLast_Receipt_Detail_PlanState_Status_1.Unique_Account_No    as varchar(10))  , @BankUnique_Account_No , 1)  > 0 and  DueDate >= @DateFrom  and DueDate <=@DateTo
								 ) qry   order by BankID,DueDate , [type] desc
								 
DECLARE @MyCursor CURSOR;
DECLARE @BankId varchar(20);
    SET @MyCursor = CURSOR FOR
    SELECT * FROM dbo.splitstring(@BankIdList)     
    OPEN @MyCursor 
    FETCH NEXT FROM @MyCursor 
    INTO @BankId
    WHILE @@FETCH_STATUS = 0
    BEGIN
    DECLARE @MandyeAvalDore AS decimal(18,0)
	set @MandyeAvalDore= isnull((select dbo.Banks.OpeningValue from Banks where BankID=@BankId),0);
	update #temp1 set mandeh= @MandyeAvalDore , @MandyeAvalDore = isnull(@MandyeAvalDore ,0)+ (isnull(priceDaryaft,0) - isnull(PricePardakht,0))	
	where BankID=@BankId
						    		 
      FETCH NEXT FROM @MyCursor 
      INTO @BankId 
    END; 
    CLOSE @MyCursor ;
    DEALLOCATE @MyCursor;
                                   select * from #temp1
		                            drop table #temp1 
!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!