-- ===== PROCEDURE GetAllBankBalanceNaghdinegi (recovered from backup text; may be incomplete) =====
CREATE PROCEDURE [dbo].[GetAllBankBalanceNaghdinegi]
   @FromDate char(8) , @ToDate char(8) 
 truncate table bankbalanceN
 declare @rCount int
 	Declare @BankID decimal(18,0) 
  --SELECT  [BankID] ,sum([debit]) Daryaft ,sum([credit]) Pardakht,sum([debit]-[credit])Balance
  --into #tmp11
  --FROM [View_Naghdinegi]
  --where [TransactionDate]<= @FromDate
  --group by  [BankID]
  CREATE TABLE #tmp11 (
balance decimal(18,0),
Dryaft decimal(18,0),
MogodiAvallie decimal(18,0),
Pardakht decimal(18,0),
basicBankId int,
BasicBankdescription nvarchar(50),
bankId int,
branchName nvarchar(50),
Bank_AccountNumber nvarchar(50))
INSERT INTO  #tmp11 (balance,Dryaft,MogodiAvallie,Pardakht,basicBankId,BasicBankdescription,bankId,branchName,Bank_AccountNumber)
EXEC GetAllBankBalance @FromDate,@FromDate
   DECLARE vend_cursor CURSOR  
    FOR  SELECT [BankID] from #tmp11
	OPEN vend_cursor  
   FETCH NEXT FROM vend_cursor into  @BankID;
    WHILE @@FETCH_STATUS = 0 
   begin
    --pardakhti saresid gozashte
	Declare @saresidGozashte decimal(18,0) 
    set @saresidGozashte = isnull(
	select sum(rp.EquivalencePrice) 
	from Request_Payment as rp 
	left join Payment as p 	
	on rp.RequestID=p.RequestID 
	where rp.Source_PaymentValue=@BankID 
	and p.PaymentDate is null 
	and rp.DueDate is not null 
	and rp.DueDate<@FromDate 
	and rp.RequestID not in (
		select  RequestID 
		from Request_Payment_StatusDetails 
		where [RequestStatusTypeID]<0) 
		and rp.RequestID in(select  RequestID from Request_Payment_StatusDetails where [RequestStatusTypeID]=4)  
		and rp.Pay_TypeDetailID_source=4
  ) , 0 )
   --tahodat emroz  
Declare @TahodatEmroz decimal(18,0) 
    set @TahodatEmroz = isnull(
	(select sum(rp.EquivalencePrice)
	from Request_Payment as rp 
	left join Payment as p 	
	on rp.RequestID=p.RequestID 
	where  rp.Source_PaymentValue=@BankID and p.PaymentDate is null and rp.DueDate is not null and rp.DueDate=@FromDate and
	rp.RequestID not in (select  RequestID from Request_Payment_StatusDetails where [RequestStatusTypeID]<0) and rp.RequestID in(select  RequestID from Request_Payment_StatusDetails where [RequestStatusTypeID]=4)  and rp.Pay_TypeDetailID_source=4
  ) , 0 )
     --pardakhtaniTo
Declare @pardakhtaniTo decimal(18,0) 
    set @pardakhtaniTo = isnull(
	select sum(rp.EquivalencePrice) from Request_Payment as rp 
	left join Payment as p 	
	on rp.RequestID=p.RequestID 
	where  rp.Source_PaymentValue=@BankID and p.PaymentDate is null and rp.DueDate is not null and rp.DueDate>=@FromDate  and rp.DueDate<=@ToDate and 
	rp.RequestID not in (select  RequestID from Request_Payment_StatusDetails where [RequestStatusTypeID]<0) and 
	rp.RequestID in(select  RequestID from Request_Payment_StatusDetails where [RequestStatusTypeID]=4)  and
	rp.Pay_TypeDetailID_source=4
  ) , 0 )
   --dargaryan vosol markaz
  Declare @dargaryanvosol decimal(18,0) 
    set @dargaryanvosol = isnull(
	(  select sum(rd.ChequePrice_Rial) from 
   Receipt_Detail rd join GetLast_Receipt_Detail_PlanState_Status() rs on rd.ReceiptDetailId=rs.ReceiptDetailId
   where rs.PlaningTypeID=2 and rd.CityID=4 and rs.Unique_Account_No=(select Unique_Account_No from  Banks where BankID=@BankID)
     ) , 0 )
   --dargaryan vosol khareg markaz
     Declare @dargaryanvosolkhareg decimal(18,0) 
    set @dargaryanvosolkhareg = isnull(
	(  select sum(rd.ChequePrice_Rial) from 
   Receipt_Detail rd join GetLast_Receipt_Detail_PlanState_Status() rs on rd.ReceiptDetailId=rs.ReceiptDetailId
   where rs.PlaningTypeID=2  and rd.CityID !=4 and rs.Unique_Account_No=(select Unique_Account_No from  Banks where BankID=@BankID)
     ) , 0 )
       insert into bankbalanceN
	 select #tmp11.balance as balance ,
	  #tmp11.Dryaft as Daryaft,
	  #tmp11.MogodiAvallie as MogodiAvalie,
	 #tmp11.Pardakht  as Pardakht,
    	#tmp11.basicBankId as BasicBankId,
	#tmp11.BasicBankdescription as BasicBankDescription ,
	 #tmp11.BankID as BankID,#tmp11.branchName as BranchName  ,#tmp11.balance Bank_AccountNumber , @saresidGozashte as  PardakhtGozashte,
	 @TahodatEmroz as  TahodatToday,@pardakhtaniTo as  PardkhtaniTo, #tmp11.balance as MogodiTrust,@dargaryanvosol as  DargaryanMarkaz,(#tmp11.balance )+@dargaryanvosol as  trustDargaryanmarkaz,@dargaryanvosolkhareg DargaryanKharegMarkaz
	 from #tmp11 
	 where #tmp11.BankID=@BankID
	select @rCount = @@ROWCOUNT
	 FETCH NEXT FROM vend_cursor into  @BankID
   end
close vend_cursor
DEALLOCATE vend_cursor;
select * from bankbalanceN 
((0))0
GO

-- ===== PROCEDURE GetAllRequestStatus (recovered from backup text; may be incomplete) =====
CREATE PROCEDURE [dbo].[GetAllRequestStatus]
    @CurrentDate varchar(8)
  --declare @CurrentDate varchar(8)
--set @CurrentDate = '13950822'
 declare @temp table
(States	 varchar(50),
DueDate	 varchar(8),
PayAmount	 bigint,
RequestID	bigint ,
RequestDate	 varchar(50),
Unique_Account_No	 varchar(50),
Account_Name	 varchar(150),
BehalfDescription  varchar(250),
BehalfGroupID int,
ChequeNo	bigint ,
Title	 varchar(250),
ForSodooreCheck	 int ,
Bank_AccountNumber  varchar(150) ,
TahvilDadeShodeh tinyint 
insert into @temp  EXEC Get_Maturity_Cheques     @CurrentDate
--select   a.RequestID, a.FiscalYear, a.UserID, a.RequestDate, a.RequestCreatedTime, a.Unique_Account_No, a.Main_Unique_Account_No, a.PayAmount, a.ExchangeTypeID, a.ExchangeRate, a.EquivalencePrice,
--	a.Priority, a.BehalfID, a.Pay_TypeDetailID_source, a.Source_TypeID, ISNULL(a.Source_PaymentValue, '') AS Source_PaymentValue, a.Destination_TypesID, a.Destination_PaymentValue, a.AggrigateOrDuplicationID, a.AggrigateOrDuplicationStatusID,
--	a.Description, a.DueDate, a.ChequeNo, a.IsWithdrawType, a.ChequeElements_PrintLayout, a.RefrenceRequestId, a.SystemId, a.SystemReferenceID, a.BankID, a.CashDeskID, a.ExchangeAmount 
select	a.*,  b.* ,
	v.Account_Name ,be.BehalfDescription,ba.Bank_AccountNumber,bas.BasicBankDescription , 
	case when c.RequestID Is null then 1 else 0 end as MozavezeChapeChequeDarad , dbo.MojavezeEmza(a.RequestID) as mojavezeEmza,
	(SELECT MAX(AccVoucherNo) FROM Voucher_Row vr WHERE a.RequestID = vr.ReferenceId) AS AccVoucherNo
--into TMP
 from Request_Payment  a left join @temp c on a.RequestID = c.RequestID 
  left join v_unique_accounts v on a.Unique_Account_No=v.Account_Code
  left join Behalfs be on be.BehalfID=a.BehalfID
  left join Banks ba on a.Source_PaymentValue=ba.BankID
  left join BasicBanks bas on bas.BasicBankId=ba.BasicBankID
OUTER APPLY  dbo.GetRequestStatus(a.RequestID ) b 
order by DueDate desc
-- select * from TMP
((1))0
GO

-- ===== PROCEDURE GetBeneficiariesDetails (recovered from backup text; may be incomplete) =====
CREATE PROCEDURE [dbo].[GetBeneficiariesDetails]
SELECT     a.*,b.Beneficiar_TEL,c.Bank_ShebaNo,c.Bank_BranchName,c.Bank_AccountNumber,d.BasicBankDescription
FROM     dbo.Beneficiaries a
left join Beneficiaries_TELS  b
ON a.BeneficiarID = b.BeneficiarID 
left join BeneficiariesDetailInfo c
ON a.BeneficiarID = c.BeneficiarID
left join BasicBanks d
on c.BankID = d.BasicBankId
order by a.BeneficiarID
