-- ===== PROCEDURE GetExchangeAvg (recovered from backup text; may be incomplete) =====
CREATE PROCEDURE [dbo].[GetExchangeAvg]
@VoucherDt			varchar(8),
@AccountNo			char(10),
@UniqueAccountNo	char(10)
SET NOCOUNT ON;
DECLARE @Ok								int,
		@AccDbName						varchar(50),
		@ExchangeAvg					decimal(18, 6),
		@Sql							nvarchar(4000);
SELECT @AccDbName = dbo.GetAccDBNameSclr(@VoucherDt);
SET @Sql = 
'WITH cte
	SELECT SUM(RialBalance) AS RialBalance, SUM(ExchangeBalance) AS ExchangeBalance
		SELECT SUM(b.Debit - b.Credit) AS RialBalance,
				SUM(CASE WHEN b.Debit > 0 THEN b.Exchange_Ammount ELSE - b.Exchange_Ammount END) AS ExchangeBalance
		FROM ' + @AccDbName + '..t_voucher a
		INNER JOIN ' + @AccDbName + '..t_voucher_row b
			ON a.Voucher_No = b.Voucher_No
		WHERE a.Voucher_Date <= @VoucherDt
			AND b.Account_No = @AccountNo
			AND ISNULL(b.Unique_Account_No, '''') = ISNULL(@UniqueAccountNo, '''')
		UNION ALL
		SELECT SUM(Debit - Credit) AS RialBalance,
				SUM(CASE WHEN Debit > 0 THEN Exchange_Ammount ELSE - Exchange_Ammount END) AS ExchangeBalance
		FROM Voucher_Row_Reciept
		WHERE AccVoucherNo IS NULL
			AND StateDate <= @VoucherDt
			AND Account_No = @AccountNo
			AND ISNULL(Unique_Account_No, '''') = ISNULL(@UniqueAccountNo, '''')
SELECT @ExchangeAvg = ISNULL(CASE WHEN ExchangeBalance = 0 THEN 0 ELSE ABS(RialBalance / ExchangeBalance) END, 0)
FROM cte;';
EXEC sp_executesql
	@Sql,
	N'@VoucherDt char(8), @AccountNo char(10), @UniqueAccountNo char(10), @ExchangeAvg decimal(18, 6) OUTPUT',
	@VoucherDt, @AccountNo, @UniqueAccountNo, @ExchangeAvg OUTPUT;
RETURN @ExchangeAvg;
((0))0
((0))0
GO

-- ===== PROCEDURE GetIntegratedRequest (recovered from backup text; may be incomplete) =====
CREATE PROCEDURE  [dbo].[GetIntegratedRequest]
	  @RequestId int ,
	  @WhereStr varchar(150)
	SET NOCOUNT ON;
declare @s varchar(2000)  
 set @s = 'SELECT        Request_Payment.RequestID ,
						 BasicBanks.BasicBankDescription as Bank, 
						 Beneficiaries_TELS.Beneficiar_TEL Tel, 
						 BeneficiariesDetailInfo.Bank_ShebaNo as Bank_Sheba,
						 BeneficiariesDetailInfo.Bank_AccountNumber as Bank_AccountNumber, 
                         Beneficiaries.LegalAccountName as LegalAccountName,
						 v_unique_accounts.Account_Code as Unique_Account_No,  
						 v_unique_accounts.Account_Name , 
					     cast (Request_Payment.PayAmount as varchar(200))  as Price
                         FROM Request_Payment
                         full JOIN  Beneficiaries ON Beneficiaries.Unique_Account_No = Request_Payment.Unique_Account_No
                         full JOIN  Beneficiaries_TELS ON Beneficiaries.BeneficiarID = Beneficiaries_TELS.BeneficiarID
                         full JOIN  BeneficiariesDetailInfo ON Beneficiaries.BeneficiarID = BeneficiariesDetailInfo.BeneficiarID
                         full JOIN  BasicBanks ON BeneficiariesDetailInfo.BankID = BasicBanks.BasicBankId
                         full JOIN  v_unique_accounts ON   Beneficiaries.Unique_Account_No = v_unique_accounts.Account_Code					
						  where   Request_Payment.AggrigateOrDuplicationID=@RequestId 
						  and	'  + 
						  @WhereStr + ' order by  Bank desc '
						  set @s = REPLACE (@s , '@RequestId' , @RequestId )
						  exec (@s)
  --Bank_Sheba ASC ,
GO

-- ===== FUNCTION GetLast_Receipt_Detail_PlanState_Status (recovered from backup text; may be incomplete) =====
CREATE FUNCTION [dbo].[GetLast_Receipt_Detail_PlanState_Status]( )
RETURNS TABLE
	RETURN (SELECT a.ReceiptDetailId , 
				   a.StateID,
				   a.StateDate
				  ,a.StateTime
				  ,a.PlaningTypeID
				  ,b.PlaningTypeDesc
				  ,a.PlaningTypeReferenceID
				  ,a.Unique_Account_No
				  ,a.Unique_Account_No_Two
				  ,a.PlaningType_Value
				  ,a.Account_No
				  ,a.RenewChequeDate
				  ,a.DecreaseChequePrice
			FROM Receipt_Detail_PlanState a
			INNER JOIN PlaningType b
				ON a.PlaningTypeID = b.PlaningTypeID
			WHERE a.StateID = (SELECT MAX(rdp.StateID) FROM Receipt_Detail_PlanState rdp 
			WHERE rdp.ReceiptDetailId = a.ReceiptDetailId));
