-- ===== FUNCTION GetLastRequestStatus (recovered from backup text; may be incomplete) =====
CREATE FUNCTION [dbo].[GetLastRequestStatus]()
RETURNS TABLE
 return (
   SELECT  [Request_Payment_StatusDetailsID]
      ,[RequestID] as Request_Payment_Status_RequestID
      ,[RequestStatusTypeID] as Request_Payment_Status_RequestStatusTypeID
      ,[StatusDetailDescription] as Request_Payment_Status_StatusDetailDescription
      ,[ActionDate] as Request_Payment_Status_ActionDate
      ,[ActionTime] as Request_Payment_Status_ActionTime
      , b.RequestStatus as Request_Payment_Status_RequestStatus
FROM Request_Payment_StatusDetails D inner join RequestStatusTypes b
  on D.RequestStatusTypeID = b.Id 
WHERE cast(d.ActionDate  as  varchar(10)) + cast(d.ActionTime  as varchar(20)) = (SELECT MAX(cast(ActionDate  as  varchar(10)) + cast(ActionTime  as varchar(20))) FROM Request_Payment_StatusDetails WHERE RequestID = D.RequestID)
