-- ===== PROCEDURE GetNextReceipt_Detail_PlanState (recovered from backup text; may be incomplete) =====
CREATE PROCEDURE [dbo].[GetNextReceipt_Detail_PlanState]
@PlaningTypeID	int
SET NOCOUNT ON;
SELECT a.ReceiptDetailId, a.Cheque_Number, a.DueDate, a.Unique_Account_No, a.ChequePrice_Rial,
	b.StateID, b.StateDate, b.PlaningTypeID, b.Unique_Account_No,
	e.PlaningTypeDesc AS PrevPlaningTypeDesc
FROM Receipt_Detail a
INNER JOIN Receipt_Detail_PlanState b
	ON a.ReceiptDetailId = b.ReceiptDetailId
INNER JOIN
	SELECT MAX(StateID) AS MaxStateID, ReceiptDetailId
	FROM Receipt_Detail_PlanState
	GROUP BY ReceiptDetailId
	ON b.StateID = c.MaxStateID
INNER JOIN PlaningTypeCirculation d
	ON b.PlaningTypeID = d.ParentPlaningTypeID
INNER JOIN PlaningType e
	ON d.ParentPlaningTypeID = e.PlaningTypeID
WHERE d.ChildPlaningTypeID = @PlaningTypeID;
