-- ===== PROCEDURE GetPettyCashHeaderAndDetails_ByPettyCashId (recovered from backup text; may be incomplete) =====
CREATE PROCEDURE [dbo].[GetPettyCashHeaderAndDetails_ByPettyCashId](
@PettyCashId INT                    
SELECT                     
                          Detail.PettyCashTransactionDetailID,
						  SUBSTRING( Detail.PayDate,1,4)+'/'+SUBSTRING( Detail.PayDate,5,2) +'/'+SUBSTRING( Detail.PayDate,7,2)  as PayDate,			
						  Detail.Description,
						  Detail.Unique_Account_No As DetailUnique_Account_No,
						  v_unique_accounts_1.Account_Name AS DetailsUnique_Account_Title,
						  v_unique_accounts_2.Account_Name AS DetailsUnique_Account_No_two_Title,
						  detail.Unique_Account_No as DetailsUnique_Account_Code,
						  detail.Unique_Account_No_two as DetailsUnique_Account_No_two_Code,
						  detail.Account_no as DetailAccount_no,
						  detail.Price,
						  detail.IsAccept,
						  detail.IsVakhahi,
						  detail.EllateVakhahi,
						  detail.IsAcceptVakhahi,
						  detail.AcceptVakhahiDate,
						  dbo.v_accounts.Account_Name AS DetailsAccountName,   
                          header.PettyCashTransactionHeaderID,
						  header.PettyCashTransactionDate,
						  header.RequestID,
						  header.IsConfirm,
						  header.UserID_Confirmer,
						  header.ConfirmDate,
						  header.VariziAmount_Or_sharjeTankhah,
						  header.Unique_Account_no_two as HeaderUnique_Account_no_two_Code,
						  dbo.v_unique_accounts.Account_Name AS HeaderUnique_Account_no_two_Title,
						  Behalfs.BehalfDescription, 
						  dbo.BehalfGroup.BehalfGroupDescription
FROM            dbo.PettyCash_TransactionDetail as Detail
                         INNER join PettyCash_TransactionHeader As header ON Detail.PettyCashTransactionHeaderID = header.PettyCashTransactionHeaderID
						 INNER JOIN BehalfGroup ON Detail.BehalfGroupID = dbo.BehalfGroup.BehalfGroupID 
						 INNER JOIN Behalfs ON Detail.BehalfID = Behalfs.BehalfID AND dbo.BehalfGroup.BehalfGroupID = Behalfs.BehalfGroupID
						 INNER JOIN v_accounts ON Detail.Account_no = dbo.v_accounts.account_code
						 LEFT OUTER JOIN v_unique_accounts AS v_unique_accounts_1 ON Detail.Unique_Account_No = v_unique_accounts_1.Account_Code
						 LEFT OUTER JOIN v_unique_accounts AS v_unique_accounts_2 ON Detail.Unique_Account_No_two = v_unique_accounts_2.Account_Code
					     LEFT OUTER JOIN v_unique_accounts ON header.Unique_Account_no_two = dbo.v_unique_accounts.Account_Code
						 where PettyCashID=@PettyCashId
GO

-- ===== PROCEDURE GetPostVoucherDateBoundraies (recovered from backup text; may be incomplete) =====
CREATE PROCEDURE [dbo].[GetPostVoucherDateBoundraies]
SET NOCOUNT ON;
SELECT MIN(MinDate) AS MinDate, MAX(MaxDate) AS MaxDate
	SELECT MIN(StateDate) AS MinDate, MAX(StateDate) AS MaxDate
	FROM Voucher_Row
	WHERE AccVoucherNo IS NULL
	UNION ALL
	SELECT MIN(StateDate) AS MinDate, MAX(StateDate) AS MaxDate
	FROM Voucher_Row_Reciept
	WHERE AccVoucherNo IS NULL
GO

-- ===== FUNCTION GetPostVoucherType (recovered from backup text; may be incomplete) =====
CREATE FUNCTION [dbo].[GetPostVoucherType](@Dt char(8))
RETURNS int
	DECLARE @PostVoucherType int;
	SELECT @PostVoucherType = PostVoucherType
	FROM Config
	WHERE @Dt BETWEEN FiscalYearStart AND FiscalYearEnd;
	IF @PostVoucherType IS NULL
		SELECT @PostVoucherType = PostVoucherType
		FROM Config
		WHERE FiscalYearEnd = (SELECT MAX(FiscalYearEnd) FROM Config WHERE FiscalYearEnd < @Dt);
	RETURN @PostVoucherType;
