-- ===== PROCEDURE GetReceipt_Detail_PlanState_Info (recovered from backup text; may be incomplete) =====
CREATE PROCEDURE [dbo].[GetReceipt_Detail_PlanState_Info]
@ReceiptDetailId decimal(18, 0)
SET NOCOUNT ON;
SELECT a.*,
	CASE WHEN a.StateID = MaxStateId THEN 1 ELSE 0 END AS IsLastStateId,
	b.PlaningTypeDesc,
	c.Account_Name AS AccountName,
	d.Account_Name AS UniqueAccountName,
	e.Account_Name AS UniqueAccountNameTwo,
	ISNULL(f.AccVoucherNo, 0) AS AccVoucherNo
	SELECT StateID, StateDate, ReceiptDetailId, PlaningTypeID, PlaningTypeReferenceID, Account_No, Unique_Account_No,
		Unique_Account_No_Two, PlaningType_Value, MAX(StateID) OVER(PARTITION BY ReceiptDetailId) AS MaxStateId
	FROM Receipt_Detail_PlanState
	WHERE ReceiptDetailId = @ReceiptDetailId
INNER JOIN PlaningType b
	ON a.PlaningTypeID = b.PlaningTypeID
LEFT OUTER JOIN v_accounts c
	ON a.Account_No = c.account_code
LEFT OUTER JOIN v_unique_accounts d
	ON a.Unique_Account_No = d.Account_Code
LEFT OUTER JOIN v_unique_accounts e
	ON a.Unique_Account_No_Two = e.Account_Code
OUTER APPLY (SELECT TOP 1 AccVoucherNo FROM Voucher_Row_Reciept v WHERE a.ReceiptDetailId = v.ReceiptDetailId AND a.StateID = v.StateId) AS f
ORDER BY StateID DESC;
GO

-- ===== PROCEDURE GetRecieptHeaderAndDetail_ByReceiptId (recovered from backup text; may be incomplete) =====
CREATE PROCEDURE [dbo].[GetRecieptHeaderAndDetail_ByReceiptId]
  @ReceiptId decimal(18,0)
select a.[ReceiptId]
      ,[ReceiptDate]
      ,[RecieptTypeId]
      ,[isRiali]
      ,[cmpBranchID] 
      , b.[ReceiptDetailId]
      ,[FiscalYear]
      ,b.[UserID]
      ,[Cheque_Number]
      ,[Cheque_OwnerName]
      ,[DueDate]
      ,b.[Unique_Account_No]
      ,[ChequePrice_Rial]
      ,1 AS ExchangeTypeID
      ,[ExchangeRate]
	  ,ExchangeAmount
      ,ChequePrice_Rial AS EquivalencePrice
      ,[BehalfID]
      ,[Description]
      ,[BankID]
      ,[Bank_AccountNo]
      ,[Bank_BranchDesc]
      ,[Bank_BranchCode]
      ,[CityID]
      ,c.StateDate
      ,c.StateTime
      ,c.PlaningTypeID
      ,c.PlaningTypeDesc
	  ,b.CashDeskID
FROM Reciept_Header a inner join Receipt_Detail  b on a.ReceiptId = b.ReceiptId
left join GetLast_Receipt_Detail_PlanState_Status() c on b.ReceiptDetailId = c.ReceiptDetailId
where a.ReceiptId = @ReceiptId
