-- ===== PROCEDURE GetRecieptHeaderAndDetail_ByRecieptTypeId (recovered from backup text; may be incomplete) =====
CREATE PROCEDURE [dbo].[GetRecieptHeaderAndDetail_ByRecieptTypeId]
@RecieptTypeId int
SET NOCOUNT ON;
SELECT  DISTINCT
	dbo.fn_ShamsiDateStrDiffDay(dbo.MiladiTOShamsi(GETDATE()), d.DueDate) AS mohlat,
	b.ReceiptId,
	b.ReceiptDate,
	b.RecieptTypeId,
	c.Receipt_Pay_TypeDetailDescription,
	b.isRiali,
	b.cmpBranchID,
	d.ReceiptDetailId,
	d.FiscalYear,
	d.UserID,
	d.Cheque_Number,
	d.Cheque_OwnerName,
	ISNULL(e.RenewChequeDate, d.DueDate) AS DueDate,
	d.Unique_Account_No AS DetailUnique_Account_No,
	d.ChequePrice_Rial AS EquivalencePrice,
	ISNULL(d.CashDeskID,0) AS ExchangeTypeID,
	d.ExchangeRate,
	d.ChequePrice_Rial,
	d.BehalfID,
	d.Description,
	d.BankID,
	d.Bank_AccountNo,
	d.Bank_BranchDesc,
	d.Bank_BranchCode,
	d.CityID,
	e.StateID,
	e.StateDate,
	e.StateTime,
	e.PlaningTypeID,
	e.PlaningTypeDesc,
	e.Unique_Account_No AS StatusUnique_Account_No_One,
	e.Unique_Account_No_Two AS StatusUnique_Account_No_Two,
	e.PlaningType_Value,
	e.Account_No AS StatusAccount_No,
	e.PlaningTypeReferenceID,
	f.User_FullName,
	'' AS ExchangeTypeDescription,
	i.BehalfGroupDescription,
	i.BehalfGroupID,
	h.BehalfDescription,
	j.CityDescription,
	k.ProvinceDescription,
	p.BasicBankDescription,
	o.Account_Name AS DetailUnique_Account_No_One_Title,
	n.Account_Name AS StatusUnique_Account_No_One_Title,
	m.Account_Name AS StatusUnique_Account_No_Two_Title,
	a.PlaningTypeDesc AS StatusPlaningType,
	l.Account_Name AS StatusAccount_Name
FROM PlaningType a
INNER JOIN Reciept_Header b
LEFT JOIN Receipt_Pay_TypeDetail c
	ON c.Receipt_Pay_TypeDetailID = b.RecieptTypeId
INNER JOIN Receipt_Detail d
	ON b.ReceiptId = d.ReceiptId
INNER JOIN GetLast_Receipt_Detail_PlanState_Status() e
	ON d.ReceiptDetailId = e.ReceiptDetailId
INNER JOIN UserInfo f
	ON d.UserID = f.UserID
--INNER JOIN ExchangeTypes g
--	ON d.ExchangeTypeID = g.ExchangeTypeID
INNER JOIN Behalfs h
	ON d.BehalfID = h.BehalfID
INNER JOIN BehalfGroup i
	ON h.BehalfGroupID = i.BehalfGroupID
INNER JOIN City j
	ON d.CityID = j.CityID
INNER JOIN Province k
	ON j.ProvinceID = k.provinceID
	ON a.PlaningTypeID = e.PlaningTypeID
LEFT OUTER JOIN v_accounts l
	ON e.Account_No = l.account_code
LEFT OUTER JOIN v_unique_accounts m
	ON e.Unique_Account_No_Two = m.Account_Code
LEFT OUTER JOIN v_unique_accounts n
	ON e.Unique_Account_No = n.Account_Code
LEFT OUTER JOIN v_unique_accounts o
	ON d.Unique_Account_No = o.Account_Code
LEFT OUTER JOIN BasicBanks p
	ON d.BankID = p.BasicBankId
WHERE b.RecieptTypeId = @RecieptTypeId;
GO

-- ===== PROCEDURE GetRecieptHeaderAndDetail_ByRecieptTypeIdsss (recovered from backup text; may be incomplete) =====
CREATE PROCEDURE [dbo].[GetRecieptHeaderAndDetail_ByRecieptTypeIdsss]
  @RecieptTypeIdss varchar(50)
select distinct a.[ReceiptId],
      a.ReferenceReceiptId
      ,[ReceiptDate]
      ,[RecieptTypeId]
      ,[isRiali]
      ,[cmpBranchID] 
      ,b.[ReceiptDetailId]
      ,[FiscalYear]
      ,b.[UserID]
      ,[Cheque_Number]
      ,[Cheque_OwnerName]
      , SUBSTRING( [DueDate],1,4)+'/'+SUBSTRING(DueDate ,5,2)+'/'+SUBSTRING(DueDate ,7,2) as DueDate
      ,b.[Unique_Account_No]
      ,cast([ChequePrice_Rial] as decimal(18,0)) as ChequePrice_Rial
      ,1 AS ExchangeTypeID
      ,[ExchangeRate]
      ,ChequePrice_Rial AS[EquivalencePrice]
      ,b.[BehalfID]
	  ,d.BehalfDescription
      ,[Description]
      ,[BankID]
      ,[Bank_AccountNo]
      ,[Bank_BranchDesc]
      ,[Bank_BranchCode]
	  ,BasicBankDescription
      ,[CityID]
      ,c.StateDate
      ,c.StateTime
      ,c.PlaningTypeID
      ,c.PlaningTypeDesc
	  , v.Account_Name 
	  , rec.Receipt_Pay_TypeDetailDescription
	  , rec.Receipt_Pay_TypeDetailDescription2
	  --, dbo.HasTaviz(b.ReceiptDetailId) AS HasTaviz
FROM Reciept_Header a 
inner join Receipt_Detail  b 
    on a.ReceiptId = b.ReceiptId
left join BasicBanks 
    on b.BankID=BasicBankId
inner join GetLast_Receipt_Detail_PlanState_Status() c
    on b.ReceiptDetailId = c.ReceiptDetailId
Left join Behalfs d
    on b.BehalfID = d.BehalfID
left join v_unique_accounts v 
	on b.Unique_Account_No = v.Account_Code 
inner join Receipt_Pay_TypeDetail rec 
	on [RecieptTypeId] = rec.Receipt_Pay_TypeDetailID
where charindex(cast( a.RecieptTypeId    as varchar(10))  , @RecieptTypeIdss , 1)  > 0
GO

