-- ===== FUNCTION GetRequestStatus (recovered from backup text; may be incomplete) =====
CREATE FUNCTION [dbo].[GetRequestStatus]( @RequestID int)
RETURNS TABLE
   --declare @VN int
 --set @VN = 156
 return(
 select  top 1 @RequestID requestId1, * 
 from (
select  b.RequestID,  a.RequestStatus  as RequestStatus 
from RequestStatusTypes a  inner   join Request_Payment_StatusDetails b
   on  a.Id = b.RequestStatusTypeID
   where b.RequestID = @RequestID
 pivot
    max(RequestID) For RequestStatus in ([Cancellation],[Unknown],[Confirmed],[ConfirmPayment],[Paid],[Delivered],[DeleiverdLasheCheque],[CovertCheque],[CancelCheque],[ExtendDueDate])
GO

-- ===== PROCEDURE GetRequstByRequestId (recovered from backup text; may be incomplete) =====
CREATE PROCEDURE [dbo].[GetRequstByRequestId] @RequestID dec
						 						
SELECT        dbo.UserInfo.User_FullName, dbo.ExchangeTypes.ExchangeTypeDescription, Behalfs.BehalfDescription, dbo.BehalfGroup.BehalfGroupDescription, 
                         Receipt_Pay_TypeDetail.Receipt_Pay_TypeDetailDescription, Request_Payment.RequestID, Request_Payment.FiscalYear, Request_Payment.UserID, Request_Payment.RequestDate, 
                         Request_Payment.RequestCreatedTime, Request_Payment.Unique_Account_No, Request_Payment.Main_Unique_Account_No, Request_Payment.PayAmount, 
                         Request_Payment.ExchangeTypeID, Request_Payment.ExchangeRate, Request_Payment.EquivalencePrice, Request_Payment.Priority, Request_Payment.BehalfID, 
                         Request_Payment.Pay_TypeDetailID_source, Request_Payment.Source_TypeID, Request_Payment.Source_PaymentValue, Request_Payment.Destination_TypesID, 
                         Request_Payment.Destination_PaymentValue, Request_Payment.AggrigateOrDuplicationID, Request_Payment.AggrigateOrDuplicationStatusID, Request_Payment.Description, 
                         Request_Payment.DueDate, Request_Payment.ChequeNo, Request_Payment.IsWithdrawType, Request_Payment.ChequeElements_PrintLayout, Request_Payment.RefrenceRequestId, 
                         dbo.v_unique_accounts.Account_Name, v_unique_accounts_1.Account_Name AS Expr1, dbo.Banks.Bank_AccountNumber, dbo.Banks.BranchCode, dbo.Banks.BranchName, BasicBanks_1.BasicBankDescription AS Expr5 , 
                         Banks_1.Bank_AccountNumber AS Expr2, Banks_1.BranchCode AS Expr3, Banks_1.BranchName AS Expr4, dbo.BasicBanks.BasicBankDescription 
FROM            Request_Payment INNER JOIN
                         dbo.UserInfo ON Request_Payment.UserID = dbo.UserInfo.UserID INNER JOIN
                         Behalfs ON Request_Payment.BehalfID = Behalfs.BehalfID INNER JOIN
                         dbo.BehalfGroup ON Behalfs.BehalfGroupID = dbo.BehalfGroup.BehalfGroupID LEFT  JOIN
                         dbo.BasicBanks AS BasicBanks_1 INNER JOIN
                         dbo.Banks AS Banks_1 ON BasicBanks_1.BasicBankId = Banks_1.BasicBankID ON Request_Payment.Destination_PaymentValue = Banks_1.BankID LEFT  JOIN
