-- ===== PROCEDURE GetStatusOfReceivableCheques (recovered from backup text; may be incomplete) =====
CREATE PROCEDURE [dbo].[GetStatusOfReceivableCheques]   @RecieptTypeIdss varchar(50),@DateNow varchar(8),@weeklyDate varchar(8),@MonthlyDate varchar(8)
	select distinct a.[ReceiptId]
      ,[ReceiptDate]
      ,[RecieptTypeId]
      ,[isRiali]
      ,[cmpBranchID] 
      ,b.[ReceiptDetailId]
      ,[FiscalYear]
      ,b.[UserID]
      ,[Cheque_Number]
      ,[Cheque_OwnerName]
      , SUBSTRING( [DueDate],1,4)+'/'+SUBSTRING(DueDate ,5,2)+'/'+SUBSTRING(DueDate ,7,2) as DueDate
	  ,case when DueDate<=@DateNow then  SUBSTRING( [DueDate],1,4)+'/'+SUBSTRING(DueDate ,5,2)+'/'+SUBSTRING(DueDate ,7,2)  else '' end   as DueToday 
	  ,case when DueDate>@DateNow  and  DueDate<= @weeklyDate then  SUBSTRING( [DueDate],1,4)+'/'+SUBSTRING(DueDate ,5,2)+'/'+SUBSTRING(DueDate ,7,2)  else '' end as WeeklyDeadline 
      ,case when DueDate<=@MonthlyDate and  DueDate>@weeklyDate and DueDate!=@DateNow then  SUBSTRING( [DueDate],1,4)+'/'+SUBSTRING(DueDate ,5,2)+'/'+SUBSTRING(DueDate ,7,2)  else '' end as MonthlyDeadline
      ,case when DueDate>@MonthlyDate then  SUBSTRING( [DueDate],1,4)+'/'+SUBSTRING(DueDate ,5,2)+'/'+SUBSTRING(DueDate ,7,2)  else '' end as AfterMonthDeadLine
      ,b.[Unique_Account_No]
      ,cast([ChequePrice_Rial] as decimal(18,0)) as ChequePrice_Rial
      ,1 AS ExchangeTypeID
      ,[ExchangeRate]
      ,ChequePrice_Rial AS EquivalencePrice
      ,[BehalfID]
      ,[Description]
      ,[BankID]
      ,[Bank_AccountNo]
      ,[Bank_BranchDesc]
      ,[Bank_BranchCode]
	  ,BasicBankDescription
      ,[CityID]
      ,c.StateDate
      ,c.StateTime
      ,c.PlaningTypeID
      ,c.PlaningTypeDesc
	  , v.Account_Name 
	  , rec.Receipt_Pay_TypeDetailDescription
	  , rec.Receipt_Pay_TypeDetailDescription2
FROM Reciept_Header a inner join Receipt_Detail  b on a.ReceiptId = b.ReceiptId
inner join BasicBanks on b.BankID=BasicBankId
inner join GetLast_Receipt_Detail_PlanState_Status() c on b.ReceiptDetailId = c.ReceiptDetailId
left join v_unique_accounts v on b.Unique_Account_No = v.Account_Code 
inner join Receipt_Pay_TypeDetail rec on [RecieptTypeId] = rec.Receipt_Pay_TypeDetailID
where charindex(cast( a.RecieptTypeId    as varchar(10))  , @RecieptTypeIdss , 1)  > 0  --and DueDate>=@DateNow and DueDate<=@MonthlyDate
order by DueDate
L@(0<L
