-- ===== FUNCTION HasVakhahiToAddHeader (recovered from backup text; may be incomplete) =====
CREATE FUNCTION [dbo].[HasVakhahiToAddHeader](@PettyCashTransactionHeaderID	decimal(18, 0))
RETURNS bit
IF EXISTS(SELECT 1
		FROM PettyCash_TransactionHeader a
		WHERE a.PettyCashTransactionHeaderID = @PettyCashTransactionHeaderID
			AND a.IsConfirm = 0
			AND EXISTS(SELECT 1
						FROM PettyCash_TransactionHeader b
						INNER JOIN PettyCash_TransactionDetail c
							ON b.PettyCashTransactionHeaderID = c.PettyCashTransactionHeaderID
								AND a.PettyCashID = b.PettyCashID
						WHERE b.PettyCashTransactionDate <= a.PettyCashTransactionDate 
							AND b.IsConfirm = 1
							AND c.IsVakhahi = 1
						)
	RETURN 1;
RETURN 0;
GO

