CREATE FUNCTION [dbo].[MojavezeEmza](@RequestID decimal(18,0))
 returns bit
 begin
-- declare @RequestID int
-- set @RequestID = 73
declare @i int , @ret bit , @j int 
set @i = 0
set @ret = 0
set @i = isnull((SELECT count(*)  FROM [PermissiveSignature_CompleteProccess] where RequestID = @RequestID ),0)
set @j = @i
if @i <> 0 
 declare @BankID int
 set @BankID =   
(SELECT   top 1      [BankID]  FROM  [PermissiveSignatureForEachBankAccount]
  where PermissiveSignatureForEachBankAccountID = 
   ( SELECT  top 1     PermissiveSignatureForEachBankAccountID  FROM [PermissiveSignature_CompleteProccess] where RequestID = @RequestID ))
set @i = @i - isnull((SELECT      count(*)  FROM  PermissiveSignatureForEachBankAccount where BankID = @BankID ),0)
declare @minSignture int
set @minSignture =  isnull((SELECT top 1  [MinPermissiveSignatureCount]   FROM  [Banks]  where BankID = @BankID ),0)
  if @i = 0 or @minSignture <= @j
    set @ret = 1
   else
    set @ret = 0
--select @i
--select @ret
return @ret
