-- ===== PROCEDURE PostVoucherErrors (recovered from backup text; may be incomplete) =====
CREATE PROCEDURE [dbo].[PostVoucherErrors]
@FromDate				char(8),
@ToDate					char(8),
@Account_No				char(8),
@Unique_Account_No		char(10),
@Unique_Account_No_two	char(10),
@Debit					decimal(18, 0),
@Credit					decimal(18, 0)
SET NOCOUNT ON;
SELECT 1 AS TransType, StateDate AS VoucherDate, ReceiptDetailId AS DocNo, StateID AS DocType,a.PlaningTypeID AS PlaningTypeID,0 AS BehalfGroupID, b.PlaningTypeDesc, a.Description , Debit, Credit
FROM Voucher_Row_Reciept  a
INNER JOIN PlaningType b
	ON a.PlaningTypeID = b.PlaningTypeID
WHERE StateDate BETWEEN @FromDate AND @ToDate
	AND (a.Account_No = @Account_No OR @Account_No IS NULL)
	AND (a.Unique_Account_No = @Unique_Account_No OR @Unique_Account_No IS NULL)
	AND (a.Unique_Account_No_two = @Unique_Account_No_two OR @Unique_Account_No_two IS NULL)
	AND a.Debit = @Debit
	AND a.Credit = @Credit
	AND a.AccVoucherNo IS NULL
UNION ALL
SELECT 2 AS TransType, StateDate AS VoucherDate, ReferenceId AS DocNo, StatusID AS DocType ,0 AS PlaningTypeID,BehalfGroupID,' ' AS PlaningTypeDesc, Description, Debit, Credit
FROM Voucher_Row
WHERE StateDate BETWEEN @FromDate AND @ToDate
	AND (Account_No = @Account_No OR @Account_No IS NULL)
	AND (Unique_Account_No = @Unique_Account_No OR @Unique_Account_No IS NULL)
	AND (Unique_Account_No_two = @Unique_Account_No_two OR @Unique_Account_No_two IS NULL)
	AND Debit = @Debit
	AND Credit = @Credit
	AND AccVoucherNo IS NULL
ORDER BY VoucherDate, TransType, DocNo, DocType;
GO

