CREATE TRIGGER Request_PaymentUpdtDelTrg ON Request_Payment
AFTER UPDATE, DELETE
SET NOCOUNT ON;
DELETE a
FROM Voucher_Row a
INNER JOIN deleted b
	ON a.ReferenceId = b.RequestID AND a.StatusID = b.Pay_TypeDetailID_source
WHERE b.Pay_TypeDetailID_source = 29;
IF @@ROWCOUNT > 0
	SELECT Request_Payment_StatusDetailsID + 0 AS Request_Payment_StatusDetailsID, RequestID, RequestStatusTypeID,
		StatusDetailDescription, ActionDate, ActionTime, HostName, UserID, OldDueDate
	INTO #t 
	FROM Request_Payment_StatusDetails
	WHERE 1 = 2;
	DELETE a
	OUTPUT deleted.* INTO #t
	FROM Request_Payment_StatusDetails a
	INNER JOIN inserted b
		ON a.RequestID = b.RequestID
	WHERE a.RequestStatusTypeID = 4;
	SET IDENTITY_INSERT Request_Payment_StatusDetails ON;
	INSERT INTO Request_Payment_StatusDetails
	(Request_Payment_StatusDetailsID, RequestID, RequestStatusTypeID, StatusDetailDescription, ActionDate,
	 ActionTime, HostName, UserID, OldDueDate)
	SELECT Request_Payment_StatusDetailsID, RequestID, RequestStatusTypeID, StatusDetailDescription, ActionDate,
		ActionTime, HostName, UserID, OldDueDate
	FROM #t;
	SET IDENTITY_INSERT Request_Payment_StatusDetails OFF;
