-- ===== PROCEDURE Show_Voucher_Row (recovered from backup text; may be incomplete) =====
CREATE PROCEDURE [dbo].[Show_Voucher_Row]
@ReferenceId bigint
SET NOCOUNT ON;
SELECT
	a.Account_No,
	a.BehalfGroupID,
	a.Credit,
	a.Date_Field,
	a.Debit,
	a.Description,
	a.Description2,
	a.Editable,
	a.Exchange_Ammount,
	a.Receipt_Pay_TypeID,
	a.ReferenceId,
	a.RowId,
	a.StatusID,
	a.Unique_Account_No,
	a.Unique_Account_No_two,
	a.User_Code,
	a.Value_Field,
	a.StateDate,
	a.record_no,
	ISNULL(b.Account_Name, '') AS Account_No_Title,
	ISNULL(c.Account_Name, '') AS Unique_Account_No_Title,
	ISNULL(d.Account_Name, '') AS Unique_Account_No_two_Title,
	a.AccVoucherNo
FROM Voucher_Row a
LEFT OUTER JOIN v_accounts b
	ON a.Account_No = b.account_code
LEFT OUTER JOIN v_unique_accounts c
	ON a.Unique_Account_No = c.Account_Code
LEFT OUTER JOIN v_unique_accounts d
	ON a.Unique_Account_No_two = d.Account_Code
WHERE a.ReferenceId = @ReferenceId;
GO

