CREATE PROCEDURE [dbo].[Show_Voucher_Row_Reciept]
@ReceiptDetailId	decimal(18, 0),
@StateID			decimal(18, 0)
SET NOCOUNT ON;
SELECT
	a.Credit AS credit,
	a.Debit AS debit,
	a.Description AS [description], 
	a.Unique_Account_No,
	a.Unique_Account_No_Two,
	a.Account_No AS Account_No,
	a.Voucher_Row_RecieptID AS Voucher_Row_RecieptID,
	a.StateId AS StateId,
	a.StateDate AS  StateDate,
	a.ReceiptDetailId AS ReceiptDetailId,
	a.PlaningTypeID AS PlaningTypeID,
	a.PlaningTypeReferenceID AS  PlaningTypeReferenceID,
	a.Value_Field AS value_Field,
	a.User_Code AS User_Code,
	a.Editable AS Editable,
	a.record_no AS record_no,
	a.Date_Field AS Date_Field,
	ISNULL(b.Account_Name, '') AS Account_No_Title,
	ISNULL(c.Account_Name, '') AS Unique_Account_No_Title,
	ISNULL(d.Account_Name, '') AS Unique_Account_No_two_Title,
	a.AccVoucherNo
FROM Voucher_Row_Reciept a
LEFT OUTER JOIN v_accounts b
	ON a.Account_No = b.account_code
LEFT OUTER JOIN v_unique_accounts c
	ON a.Unique_Account_No = c.Account_Code
LEFT OUTER JOIN v_unique_accounts d
	ON a.Unique_Account_No_two = d.Account_Code
