-- ===== PROCEDURE Sp_PaymentChequeReport (recovered from backup text; may be incomplete) =====
CREATE PROCEDURE [dbo].[Sp_PaymentChequeReport]
@PaymentID Decimal(18,0)
SELECT     Behalfs.BehalfDescription, dbo.BehalfGroup.BehalfGroupDescription, dbo.Payment.PaymentID, Request_Payment.RequestID, dbo.v_unique_accounts.Account_Name, 
                      Request_Payment.PayAmount, Request_Payment.ExchangeRate, Request_Payment.DueDate, Request_Payment.ChequeNo, Request_Payment.UserID, 
                      dbo.Banks.Bank_AccountNumber, dbo.Banks.BranchName, dbo.BasicBanks.BasicBankDescription, dbo.UserInfo.User_FullName, UserInfo_1.User_FullName AS UserInfo_1_User_FullName, 
                      dbo.v_unique_accounts.Account_Code
                      ,  dbo.BehalfGroup.UseForWithdraw, Request_Payment.RequestDate, dbo.Payment.PaymentDate, Request_Payment.IsWithdrawType
FROM         dbo.BasicBanks INNER JOIN
                      dbo.Banks ON dbo.BasicBanks.BasicBankId = dbo.Banks.BasicBankID INNER JOIN
                      dbo.PermissiveSignatureForEachBankAccount ON dbo.Banks.BankID = dbo.PermissiveSignatureForEachBankAccount.BankID INNER JOIN
                      dbo.BehalfGroup INNER JOIN
                      Behalfs ON dbo.BehalfGroup.BehalfGroupID = Behalfs.BehalfGroupID INNER JOIN
                      Request_Payment ON Behalfs.BehalfID = Request_Payment.BehalfID INNER JOIN
                      dbo.Payment ON Request_Payment.RequestID = dbo.Payment.RequestID INNER JOIN
                      dbo.PermissiveSignature_CompleteProccess ON dbo.Payment.RequestID = dbo.PermissiveSignature_CompleteProccess.RequestID ON 
                      dbo.PermissiveSignatureForEachBankAccount.PermissiveSignatureForEachBankAccountID = dbo.PermissiveSignature_CompleteProccess.PermissiveSignatureForEachBankAccountID INNER JOIN
                      dbo.PermissiveSignatures ON dbo.PermissiveSignatureForEachBankAccount.PermissiveSignatureID = dbo.PermissiveSignatures.PermissiveSignatureID INNER JOIN
                      dbo.UserInfo ON dbo.PermissiveSignatures.UserID = dbo.UserInfo.UserID INNER JOIN
                      dbo.UserInfo AS UserInfo_1 ON dbo.Payment.UserID = UserInfo_1.UserID INNER JOIN
                      dbo.v_unique_accounts ON Request_Payment.Unique_Account_No = dbo.v_unique_accounts.Account_Code
                      where Payment.PaymentID = @PaymentID
GO

-- ===== PROCEDURE sp_renamediagram (recovered from backup text; may be incomplete) =====
	CREATE PROCEDURE dbo.sp_renamediagram
		@diagramname 		sysname,
		@owner_id		int	= null,
		@new_diagramname	sysname
	WITH EXECUTE AS 'dbo'
	BEGIN
		set nocount on
		declare @theId 			int
		declare @IsDbo 			int
		declare @UIDFound 		int
		declare @DiagId			int
		declare @DiagIdTarg		int
		declare @u_name			sysname
		if((@diagramname is null) or (@new_diagramname is null))
		begin
			RAISERROR ('Invalid value', 16, 1);
			return -1
		EXECUTE AS CALLER;
		select @theId = DATABASE_PRINCIPAL_ID();
		select @IsDbo = IS_MEMBER(N'db_owner'); 
		if(@owner_id is null)
			select @owner_id = @theId;
		REVERT;
		select @u_name = USER_NAME(@owner_id)
		select @DiagId = diagram_id, @UIDFound = principal_id from dbo.sysdiagrams where principal_id = @owner_id and name = @diagramname 
		if(@DiagId IS NULL or (@IsDbo = 0 and @UIDFound <> @theId))
		begin
			RAISERROR ('Diagram does not exist or you do not have permission.', 16, 1)
			return -3
		-- if((@u_name is not null) and (@new_diagramname = @diagramname))	-- nothing will change
		--	return 0;
		if(@u_name is null)
			select @DiagIdTarg = diagram_id from dbo.sysdiagrams where principal_id = @theId and name = @new_diagramname
		else
			select @DiagIdTarg = diagram_id from dbo.sysdiagrams where principal_id = @owner_id and name = @new_diagramname
		if((@DiagIdTarg is not null) and  @DiagId <> @DiagIdTarg)
		begin
			RAISERROR ('The name is already used.', 16, 1);
			return -2
		end		
		if(@u_name is null)
			update dbo.sysdiagrams set [name] = @new_diagramname, principal_id = @theId where diagram_id = @DiagId
		else
			update dbo.sysdiagrams set [name] = @new_diagramname where diagram_id = @DiagId
		return 0
GO

-- ===== PROCEDURE sp_upgraddiagrams (recovered from backup text; may be incomplete) =====
	CREATE PROCEDURE dbo.sp_upgraddiagrams
	BEGIN
		IF OBJECT_ID(N'dbo.sysdiagrams') IS NOT NULL
			return 0;
		CREATE TABLE dbo.sysdiagrams
			name sysname NOT NULL,
			principal_id int NOT NULL,	-- we may change it to varbinary(85)
			diagram_id int PRIMARY KEY IDENTITY,
			version int,
			definition varbinary(max)
			CONSTRAINT UK_principal_name UNIQUE
				principal_id,
				name
		/* Add this if we need to have some form of extended properties for diagrams */
		IF OBJECT_ID(N'dbo.sysdiagram_properties') IS NULL
		BEGIN
			CREATE TABLE dbo.sysdiagram_properties
				diagram_id int,
				name sysname,
				value varbinary(max) NOT NULL
		IF OBJECT_ID(N'dbo.dtproperties') IS NOT NULL
		begin
			insert into dbo.sysdiagrams
				[name],
				[principal_id],
				[version],
				[definition]
			select	 
				convert(sysname, dgnm.[uvalue]),
				DATABASE_PRINCIPAL_ID(N'dbo'),			-- will change to the sid of sa
				0,							-- zero for old format, dgdef.[version],
				dgdef.[lvalue]
			from dbo.[dtproperties] dgnm
				inner join dbo.[dtproperties] dggd on dggd.[property] = 'DtgSchemaGUID' and dggd.[objectid] = dgnm.[objectid]	
				inner join dbo.[dtproperties] dgdef on dgdef.[property] = 'DtgSchemaDATA' and dgdef.[objectid] = dgnm.[objectid]
			where dgnm.[property] = 'DtgSchemaNAME' and dggd.[uvalue] like N'_EA3E6268-D998-11CE-9454-00AA00A3F36E_' 
			return 2;
		return 1;
GO

-- ===== FUNCTION splitstring (recovered from backup text; may be incomplete) =====
CREATE FUNCTION [dbo].[splitstring] ( @stringToSplit VARCHAR(MAX) )
RETURNS
 @returnList TABLE ([Name] [nvarchar] (500))
 DECLARE @name NVARCHAR(255)
 DECLARE @pos INT
 WHILE CHARINDEX(',', @stringToSplit) > 0
 BEGIN
  SELECT @pos  = CHARINDEX(',', @stringToSplit)  
  SELECT @name = SUBSTRING(@stringToSplit, 1, @pos-1)
  INSERT INTO @returnList 
  SELECT @name
  SELECT @stringToSplit = SUBSTRING(@stringToSplit, @pos+1, LEN(@stringToSplit)-@pos)
 INSERT INTO @returnList
 SELECT @stringToSplit
       exec [_SendVoucher_SpecialDate] ''   ,   1   ,  1    , 0
 RETURN
GO

-- ===== PROCEDURE t_Accounts (recovered from backup text; may be incomplete) =====
CREATE PROCEDURE [dbo].[t_Accounts]
declare @accDbname varchar(50)
set @accDbname = isnull( (SELECT  TOP (1) AccDatabaseName  FROM Config ORDER BY FiscalYear DESC) , '')
if @accDbname<>''
declare @str varchar(4000)
set @str = ' SELECT     accounts.account_code, accounts.Account_Name,   accounts.Has_Exchange_Transaction, accounts.Exchange_Type, 
                      accounts.Has_Sub_Subsidery, accounts.Has_Unique_Account,accounts.Has_Unique_Account_Two ,accounts.Has_Value_Field, accounts.Has_Date_Field, 
                       accounts.Account_Name2                      
FROM  '  +  @accDbname + '.dbo.t_accounts accounts CROSS JOIN
                      '  +  @accDbname + '.dbo.t_globals globals
where LEN(rtrim(account_code)) = globals.Group_Account_Length +  globals.General_Account_Length +  globals.Subsidery_Account_Length    
and Has_Sub_Subsidery = 0  and Is_Inactive = 0
union all
SELECT        accounts.account_code, accounts.Account_Name,  
  accounts.Has_Exchange_Transaction, accounts.Exchange_Type, 
                      accounts.Has_Sub_Subsidery, accounts.Has_Unique_Account,accounts.Has_Unique_Account_Two ,
                       accounts.Has_Value_Field, accounts.Has_Date_Field, 
                       accounts.Account_Name2     
FROM  '  +  @accDbname + '.dbo.t_accounts accounts CROSS JOIN
                      '  +  @accDbname + '.dbo.t_globals globals
where LEN(rtrim(account_code)) > globals.Group_Account_Length +  globals.General_Account_Length +  globals.Subsidery_Account_Length       and Is_Inactive = 0  '
exec(@str)
	ON a.Account_No = b.account_code
LEFT OUTER JOIN v_unique_accounts c
	ON a.Unique_Account_No = c.Account_Code
LEFT OUTER JOIN v_unique_accounts d
	ON a.Unique_Account_No_two = d.Account_Code
WHERE a.ReferenceId = @ReferenceId;
