-- ===== PROCEDURE t_unique_account_type (recovered from backup text; may be incomplete) =====
CREATE PROCEDURE [dbo].[t_unique_account_type]
declare @accDbname varchar(50)
set @accDbname = isnull( (SELECT  TOP (1) AccDatabaseName  FROM Config ORDER BY FiscalYear DESC) , '')
--select @accDbname as accDbname
if @accDbname<>''
declare @str varchar(1000)
set @str = 'SELECT* FROM '  +  @accDbname + '.dbo.t_unique_account_type '  
exec (@str)
GO

-- ===== PROCEDURE t_unique_Accounts (recovered from backup text; may be incomplete) =====
CREATE PROCEDURE [dbo].[t_unique_Accounts]
 @UniqueType  int
--declare @UniqueType  int
--set @UniqueType = -1  -- ALL OF DATA
declare @WhereStr varchar(50)
if @UniqueType = -1  
 set @WhereStr = ''
  set @WhereStr = ' where cast(  type_code  as  int)  = '  +  CAST(@uniqueType as varchar(4))
declare @accDbname varchar(50)
set @accDbname = isnull( (SELECT  TOP (1) AccDatabaseName  FROM Config ORDER BY FiscalYear DESC) , '')
--select @accDbname as accDbname
if @accDbname<>''
declare @str varchar(1000)
set @str = 'SELECT account_code , account_name FROM '  +  @accDbname + '.dbo.t_unique_accounts ' + @WhereStr
exec (@str)
GO

-- ===== FUNCTION TahvilDadeShode (recovered from backup text; may be incomplete) =====
CREATE FUNCTION [dbo].[TahvilDadeShode] (@RequestId decimal(18,0))
returns tinyint
--declare @RequestId decimal(18,0)
--set @RequestId = 744
declare @ret int
set @ret = 0
if exists( 
SELECT TOP 1   [RequestID]      
FROM  [Request_Payment_StatusDetails] where requestid =@RequestId and RequestStatusTypeID=4 and RequestID 
not  in (select RequestID from Request_Payment_StatusDetails where  requestid =@RequestId and RequestStatusTypeID = -1  ))
	set @ret = 1   -- tahvil dade shode
if exists( 
SELECT TOP 1   [RequestID]      
FROM  [Request_Payment_StatusDetails] where requestid =@RequestId and RequestStatusTypeID=4 and RequestID 
in (select RequestID from Request_Payment_StatusDetails where  requestid =@RequestId and RequestStatusTypeID = -1  ))
	set @ret = -1  -- tahvil dade shodeye cancel shode
if not exists( 
SELECT   [RequestID]      
FROM  [Request_Payment_StatusDetails] where requestid =@RequestId and RequestStatusTypeID=4  )
	set @ret = 0   -- tahvil dade nashode
--select @ret
return @ret
GO

