-- ===== PROCEDURE UpdatePaymentDateFor_TajmieeErrorData (recovered from backup text; may be incomplete) =====
CREATE PROCEDURE [dbo].[UpdatePaymentDateFor_TajmieeErrorData]
--- agar be khater e bug tarikhe tajmiee ba payment barabar nabood . yeki mishavad
SELECT    AggrigateOrDuplicationID ,  PaymentID, a.RequestID, PaymentDate, PaymentTime, a.UserID, HostName, AccVoucherNo, Effective, Canceled
into #tmp1
FROM         Payment  A inner join Request_Payment b on a.RequestID = b.RequestID 
 and AggrigateOrDuplicationID is not null
 select distinct  a.AggrigateOrDuplicationID , a.PaymentDate , b.RequestDate  
 into #tmp2
 from #tmp1  a inner join Request_Payment b
 on a.AggrigateOrDuplicationID = b.RequestID and a.PaymentDate <> b.RequestDate 
 update a
 set a.requestDate = b.PaymentDate 
 from request_Payment a inner join #tmp2 b on a.RequestID = b.AggrigateOrDuplicationID 
 --select * from #tmp2 
 --select * from request_Payment a inner join #tmp2 b on a.RequestID = b.AggrigateOrDuplicationID 
 drop table #tmp1 
 drop table #tmp2
