-- ===== VIEW v_accounts (recovered from backup text; may be incomplete) =====
CREATE VIEW [dbo].[v_accounts]
SELECT     ltrim(rtrim(accounts.account_code)) account_code, accounts.Account_Name, accounts.Has_Exchange_Transaction, accounts.Exchange_Type, 
                      accounts.Has_Sub_Subsidery, accounts.Has_Unique_Account, accounts.Has_Unique_Account_Two, accounts.Has_Value_Field, accounts.Has_Date_Field, 
                      accounts.Account_Name2
FROM         Accyaran1401.dbo.t_accounts AS accounts INNER JOIN
                      Accyaran1401.dbo.t_globals AS globals ON LEN(RTRIM(accounts.account_code)) 
                      = globals.Group_Account_Length + globals.General_Account_Length + globals.Subsidery_Account_Length
WHERE     (accounts.Has_Sub_Subsidery = 0) AND (accounts.Is_Inactive = 0)
UNION ALL
SELECT     ltrim(rtrim(accounts.account_code)) account_code, accounts.Account_Name, accounts.Has_Exchange_Transaction, accounts.Exchange_Type, 
                      accounts.Has_Sub_Subsidery, accounts.Has_Unique_Account, accounts.Has_Unique_Account_Two, accounts.Has_Value_Field, accounts.Has_Date_Field, 
                      accounts.Account_Name2
FROM         Accyaran1401.dbo.t_accounts AS accounts INNER JOIN
                      Accyaran1401.dbo.t_globals AS globals ON LEN(RTRIM(accounts.account_code)) 
                      > globals.Group_Account_Length + globals.General_Account_Length + globals.Subsidery_Account_Length
WHERE     LEN(rtrim(account_code)) > globals.Group_Account_Length + globals.General_Account_Length + globals.Subsidery_Account_Length AND Is_Inactive = 0
GO

-- ===== VIEW v_CostAccounts (recovered from backup text; may be incomplete) =====
CREATE VIEW [dbo].[v_CostAccounts]
SELECT a.account_code, a.Account_Name, a.Has_Sub_Subsidery,
	a.Has_Unique_Account, a.Has_Unique_Account_Two, a.Has_Value_Field, a.Has_Date_Field, a.Account_Name2,
	a.Is_Debit_Credit_Both, a.Has_Exchange_Transaction, a.Exchange_Type, a.Exchange_Transaction_Type
FROM Accyaran1401..t_accounts AS a
CROSS JOIN Accyaran1401..t_globals AS g
INNER JOIN Accyaran1401..t_accounts b
	ON b.account_code = LEFT(a.account_code, g.Group_Account_Length)
	b.Group_Type = 1
		(LEN(a.Account_Code) = g.Group_Account_Length + g.General_Account_Length + g.Subsidery_Account_Length + g.Subsubsidery_Account_Length)
		(LEN(a.Account_Code) = g.Group_Account_Length + g.General_Account_Length + g.Subsidery_Account_Length) AND (a.Has_Sub_Subsidery = 0)
GO

