CREATE VIEW [dbo].[v_ExchangeAccounts]
SELECT a.account_code, a.Account_Name, a.Has_Exchange_Transaction
FROM v_accounts a
INNER JOIN v_GroupAccounts b
	ON LEFT(a.account_code, LEN(b.AccGroupId)) = b.AccGroupId
WHERE a.Has_Unique_Account = 1
	AND b.Is_Debit_Credit_Both = 0;
