-- ===== VIEW ViewCashPayment (recovered from backup text; may be incomplete) =====
CREATE VIEW [dbo].[ViewCashPayment]
SELECT     CashDesk.CashDeskDescription, CashDesk.CashDeskID, 0 AS FirstdayCash, 0 AS Receipt, SUM(Request_Payment.EquivalencePrice) AS Payment, 0 AS EndDayCash, 
                      Request_Payment.RequestDate AS ActionDate
FROM         Request_Payment INNER JOIN
                      CashDesk ON Request_Payment.Source_PaymentValue = CashDesk.CashDeskID
WHERE     (Request_Payment.Source_TypeID = 2)
GROUP BY Request_Payment.RequestDate, CashDesk.CashDeskDescription, CashDesk.CashDeskID
GO

-- ===== VIEW ViewCashReceipt (recovered from backup text; may be incomplete) =====
CREATE VIEW [dbo].[ViewCashReceipt]
SELECT     CashDesk.CashDeskDescription, CashDesk.CashDeskID, 0 AS FirstdayCash, SUM(Receipt_Detail.ChequePrice_Rial) AS Receipt, 0 AS Payment, 0 AS EndDayCash, 
                      Reciept_Header.ReceiptDate AS ActionDate
FROM         Reciept_Header INNER JOIN
                      Receipt_Detail ON Reciept_Header.ReceiptId = Receipt_Detail.ReceiptId INNER JOIN
                      CashDesk ON Reciept_Header.ReferenceReceiptId = CashDesk.CashDeskID
WHERE     (Reciept_Header.RecieptTypeId = 22)
GROUP BY CashDesk.CashDeskDescription, CashDesk.CashDeskID, Reciept_Header.ReceiptDate
