-- ===== VIEW ViewPaymentChequeReport (recovered from backup text; may be incomplete) =====
CREATE VIEW [dbo].[ViewPaymentChequeReport]
SELECT Behalfs.BehalfDescription, BehalfGroup.BehalfGroupDescription, Payment.PaymentID, Request_Payment.RequestID, v_unique_accounts.Account_Name, Request_Payment.PayAmount, 
       Request_Payment.ExchangeRate, Request_Payment.DueDate, Request_Payment.ChequeNo, Request_Payment.UserID, Banks.Bank_AccountNumber, Banks.BranchName, 
       BasicBanks.BasicBankDescription, UserInfo.User_FullName, UserInfo_1.User_FullName AS Expr1, v_unique_accounts.Account_Code
FROM BasicBanks INNER JOIN
	Banks ON BasicBanks.BasicBankId = Banks.BasicBankID INNER JOIN
	PermissiveSignatureForEachBankAccount ON Banks.BankID = PermissiveSignatureForEachBankAccount.BankID INNER JOIN
	BehalfGroup INNER JOIN
	Behalfs ON BehalfGroup.BehalfGroupID = Behalfs.BehalfGroupID INNER JOIN
	Request_Payment ON Behalfs.BehalfID = Request_Payment.BehalfID INNER JOIN
	Payment ON Request_Payment.RequestID = Payment.RequestID INNER JOIN
	PermissiveSignature_CompleteProccess ON Payment.RequestID = PermissiveSignature_CompleteProccess.RequestID ON 
	PermissiveSignatureForEachBankAccount.PermissiveSignatureForEachBankAccountID = PermissiveSignature_CompleteProccess.PermissiveSignatureForEachBankAccountID INNER JOIN
	PermissiveSignatures ON PermissiveSignatureForEachBankAccount.PermissiveSignatureID = PermissiveSignatures.PermissiveSignatureID INNER JOIN
	UserInfo ON PermissiveSignatures.UserID = UserInfo.UserID INNER JOIN
	UserInfo AS UserInfo_1 ON Payment.UserID = UserInfo_1.UserID INNER JOIN
	v_unique_accounts ON Request_Payment.Unique_Account_No = v_unique_accounts.Account_Code
!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!
