-- ===== VIEW vReceipt_DetailsInfo (recovered from backup text; may be incomplete) =====
CREATE VIEW [dbo].[vReceipt_DetailsInfo]
SELECT a.ReceiptId, a.ReceiptDetailId, b.StateID, b.StateDate, a.DueDate, b.RenewChequeDate, b.PlaningTypeID, c.PlaningTypeDesc,
	a.Unique_Account_No AS RD_UniqueAccNo, u1.Account_Name AS ZinafName, a.ChequePrice_Rial, b.DecreaseChequePrice,
	b.Unique_Account_No AS PS_UniqueAccNo, u3.Account_Name,
	e.BehalfGroup_Account, v1.Account_Name AS BehafAccName,
	b.BankID, f.BranchName, f.BranchCode,
	f.Account_No AS BankVosoolAccNo, v2.Account_Name AS BankVosoolAccName,
	f.Assign_Account_No AS BankVagozarAccNo, v3.Account_Name AS BankVagozarAccName,
	f.Returns_Account_No AS BankVakhastAccNo, v4.Account_Name AS BankVakhastAccName,
	f.Unique_Account_No AS BankUniqueNo, u2.Account_Name AS BankUniqueName,
	a.CashDeskID
FROM Receipt_Detail a
INNER JOIN Receipt_Detail_PlanState b
	ON a.ReceiptDetailId = b.ReceiptDetailId
INNER JOIN PlaningType c
	ON b.PlaningTypeID = c.PlaningTypeID
LEFT OUTER JOIN Behalfs d
	ON a.BehalfID = d.BehalfID
LEFT OUTER JOIN BehalfGroup e
	ON d.BehalfGroupID = e.BehalfGroupID
LEFT OUTER JOIN Banks f
	ON b.BankID = f.BankID
LEFT OUTER JOIN v_unique_accounts u1
	ON a.Unique_Account_No = u1.account_code
LEFT OUTER JOIN v_unique_accounts u2
	ON f.Unique_Account_No = u2.account_code
LEFT OUTER JOIN v_unique_accounts u3
	ON b.Unique_Account_No = u3.account_code
LEFT OUTER JOIN v_accounts v1
	ON e.BehalfGroup_Account = v1.account_code
LEFT OUTER JOIN v_accounts v2
	ON f.Account_No = v2.account_code
LEFT OUTER JOIN v_accounts v3
	ON f.Assign_Account_No = v3.account_code
LEFT OUTER JOIN v_accounts v4
	ON f.Returns_Account_No = v4.account_code;
GO

-- ===== VIEW vVoucher_Row_Reciept (recovered from backup text; may be incomplete) =====
CREATE VIEW [dbo].[vVoucher_Row_Reciept]
WITH cte
	SELECT a.Voucher_Row_RecieptID AS VID, a.StateId, a.StateDate, a.ReceiptDetailId, a.PlaningTypeID,
		a.Description, a.Account_No, a.Unique_Account_No, a.Debit,
		b.Voucher_Row_RecieptID AS CredVID, b.StateId AS CredStateId, b.StateDate AS CredStateDate,
		b.PlaningTypeID AS CredPlaningTypeID, b.Description AS CredDescription, b.Unique_Account_No AS CredUnique_Account_No, b.Credit,
		CASE WHEN b.Voucher_Row_RecieptID IS NULL THEN 'Open' ELSE 'Close' END AS PlanStatus
	FROM Voucher_Row_Reciept a
	OUTER APPLY
		SELECT top 1 *
		FROM Voucher_Row_Reciept b
		WHERE a.ReceiptDetailId = b.ReceiptDetailId
			AND a.Account_No = b.Account_No
			AND a.Voucher_Row_RecieptID < b.Voucher_Row_RecieptID
			AND b.Credit > 0
		ORDER BY b.Voucher_Row_RecieptID
	WHERE a.Debit > 0
	UNION ALL
	SELECT a.Voucher_Row_RecieptID, a.StateId, a.StateDate, a.ReceiptDetailId, a.PlaningTypeID, a.Description, a.Account_No, a.Unique_Account_No, NULL,
		NULL, NULL, NULL, NULL, NULL, NULL,  a.Credit, 'Openx'
	FROM Voucher_Row_Reciept a
	WHERE a.Credit > 0
		AND NOT EXISTS(SELECT 1
					   FROM Voucher_Row_Reciept b
					   WHERE a.ReceiptDetailId = b.ReceiptDetailId
						AND a.Account_No = b.Account_No
						AND a.Voucher_Row_RecieptID > b.Voucher_Row_RecieptID
						AND b.Debit > 0)
	SELECT a.VID, a.StateId, a.StateDate, a.ReceiptDetailId, a.PlaningTypeID, a.Description, a.Account_No, a.Unique_Account_No,
		CASE WHEN a.Debit IS NOT NULL THEN a.Debit ELSE 0 END AS Debit,
		CASE WHEN a.Debit IS NULL THEN a.Credit ELSE 0 END AS Credit,
		0 AS CredVID, PlanStatus
	FROM cte a
	WHERE Debit > 0 OR CredVID IS NULL
	UNION ALL
	SELECT a.VID, a.CredStateId, a.CredStateDate, a.ReceiptDetailId, a.CredPlaningTypeID, a.CredDescription, a.Account_No, a.CredUnique_Account_No,
		0, Credit, CredVID, PlanStatus
	FROM cte a
	WHERE Credit > 0 AND  Debit IS NOT NULL
SELECT TOP 9223372036854775807 a.*, CASE WHEN a.CredVID IS NULL OR a.Debit IS NULL THEN 'Open' ELSE 'Close' END AS Status,
	b.PlaningTypeDesc, c.Account_Name AS AccountName, d.Account_Name AS UniqueAccountName
FROM cte2 a
INNER JOIN PlaningType b
	ON a.PlaningTypeID = b.PlaningTypeID
LEFT OUTER JOIN v_accounts c
	ON a.Account_No = c.account_code
LEFT OUTER JOIN v_unique_accounts d
	ON a.Unique_Account_No = d.Account_Code
ORDER BY VID;
