DELETE FROM Request_Payment_StatusDetails WHERE RequestID = @RequestID;
DELETE FROM PermissiveSignature_CompleteProccess WHERE RequestID = @RequestID;
DELETE FROM Request_Payment WHERE RequestID = @RequestID;
COMMIT TRANSACTION;
